/* Keep authoring helpers local when loaded as a classic browser script. */
(function () {
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('mute','Mute came through Old French muet from Latin mutus, “silent or speechless,” probably echoing a closed mouth.',[C('mute.s1','沉默状态','After the unexpected result was announced, the usually talkative room fell mute for several seconds.','意外结果公布后，平时热闹的房间沉默了几秒。','After the unexpected result was announced / the usually talkative room fell mute / for several seconds.','mute 作形容词描述不说话或陷入沉默的人、场景。','消息公布后众人一时沉默。'),C('mute.s2','无声设备','The security camera records a mute video stream, so investigators rely on the image rather than sound.','这台安防摄像机录下的是无声视频流，因此调查人员只能依据画面而非声音。','The security camera records a mute video stream / so investigators rely on the image / rather than sound.','mute 也可形容设备或媒体没有声音。','录像只有画面，没有音轨。'),C('mute.s3','调低声音','Please mute the microphone while the other speaker presents to prevent feedback from the loudspeakers.','另一位演讲者发言时请把麦克风静音，以免扬声器产生回授啸叫。','Please mute the microphone / while the other speaker presents / to prevent feedback / from the loudspeakers.','mute 作及物动词表示关闭声音，也可指使人不再发言。','关闭麦克风可防止回授噪音。'),C('mute.s4','乐器弱音器','The trumpet player fitted a mute into the bell to soften the sound during the quiet passage.','小号手把弱音器装进喇叭口，以便在轻柔乐段中减弱音量。','The trumpet player fitted a mute into the bell / to soften the sound / during the quiet passage.','mute 作可数名词指安装在乐器上以减弱音量或改变音色的装置。','弱音器装在小号上改变声音。')],M('The technician muted the video by turning its volume up until every word was louder.','The technician muted the video by switching off its sound.','把音量调高会增大声音，不是静音。','meaning'),[q('What happened after the surprising announcement?','the room became silent','the room became a camera','everyone turned on loud music','fell mute 表示一时沉默。',1),q('What is missing from the camera stream?','sound','images','the recording time','mute video stream 没有声音。',2),q('Why should the microphone be muted during the other talk?','to prevent audio feedback','to improve the camera picture','to add a second speaker','关闭麦克风能防止回授。',3,'context'),q('What did the trumpet player fit into the instrument?','a device that softens its sound','a silent video','a second mouthpiece for speech','名词 mute 指乐器弱音器。',4,'meaning')]);
P('muted','Muted is the past participle of mute and describes sound made quieter or colours and feelings kept soft or subdued.',C('muted.s1','柔和色彩','The gallery painted the small waiting room in muted greens and greys so the bright medical signs would remain easy to notice.','画廊把小候诊室刷成柔和的绿色和灰色，让鲜亮的医疗标识仍然醒目。','The gallery painted the small waiting room in muted greens and greys / so the bright medical signs / would remain easy to notice.','muted 修饰色彩时表示柔和、不鲜亮；修饰声音或情绪也可表示压低、克制。','墙面颜色不抢眼，衬托明亮标识。'),M('The designer chose muted colours, using the brightest neon shades to make the entire room vivid.','The designer chose muted colours, using soft greens and greys rather than bright neon shades.','鲜艳霓虹色不是柔和暗淡的 muted 色彩。','confusable'),[q('Which colours were used in the waiting room?','soft greens and greys','bright neon pink and orange','only black lettering','柔和的绿灰色属于 muted colours。'),q('Why were the wall colours subdued?','so the medical signs stayed noticeable','to hide the signs completely','to make the room noisier','不鲜亮的背景让标识醒目。'),q('A muted voice is?','quiet or restrained','extremely loud','impossible to hear because it is absent','muted 可表示声音被压低。',1,'meaning'),q('Which palette is muted?','soft grey-blue and dusty green','fluorescent yellow and vivid red','a flashing rainbow display','低饱和、柔和的颜色是 muted。',1,'context')]);
P('mutinous','Mutinous is mutiny plus -ous and describes people taking part in, or showing rebellious discontent like, a mutiny.',C('mutinous.s1','抗命情绪','After the officers cancelled shore leave for a third time, mutinous sailors refused to return to their duties.','军官第三次取消上岸休假后，心怀叛意的水手拒绝回去执行职责。','After the officers cancelled shore leave for a third time / mutinous sailors refused / to return to their duties.','mutinous 作形容词描述参与叛变或显露集体抗命情绪的人。','水手集体拒绝执行命令，体现抗命倾向。','军事'),M('The captain called the sailors mutinous even though they obeyed every order and expressed no discontent.','The captain called the sailors mutinous after they collectively refused the officers’ orders.','服从命令且没有反抗情绪不符合 mutinous 的意思。','meaning'),[q('Why did the sailors refuse to return to duty?','shore leave had been cancelled repeatedly','the ship had reached its destination','they had been promoted','反复取消休假引发了抗命。'),q('Mutinous most nearly describes people who are?','rebellious toward their officers','quietly following all instructions','new to a ship','mutinous 表示叛变或抗命的。'),q('Which crew seems mutinous?','sailors who jointly refuse a lawful order','sailors who report for duty as assigned','sailors who ask one polite question','集体拒绝命令体现叛变倾向。',1,'context'),q('Mutinous is built from mutiny plus?','-ous','-ly','-ment','-ous 构成表示“有……特征的”形容词。',1,'word-formation')]);
P('mutiny','Mutiny entered English through French mutiner, “to revolt,” ultimately linked to Latin movere (“to move”); it is a revolt against authority.',[C('mutiny.s1','军中叛变','The captain prevented a mutiny when the sailors’ complaints were heard and their unsafe orders were reviewed.','水手的抱怨得到倾听、危险命令也被重新审查后，船长阻止了一场哗变。','The captain prevented a mutiny / when the sailors’ complaints were heard / and their unsafe orders were reviewed.','mutiny 作名词指士兵或水手反抗军官的叛变。','船员集体不满原本可能发展为哗变。','军事'),C('mutiny.s2','集体抗命','The crew mutinied by refusing as a group to sail into the storm after the navigation warning was issued.','收到航行警报后，船员集体拒绝驶入风暴区，发动了抗命。','The crew mutinied / by refusing as a group / to sail into the storm / after the navigation warning was issued.','mutiny 也可作动词，表示一群人拒绝服从命令并反叛。','全体船员共同违令。','军事')],M('The crew staged a mutiny by following the officers’ orders without protest.','The crew staged a mutiny by collectively refusing the officers’ orders.','服从命令不属于反叛。','meaning'),[q('What did the sailors’ complaints help prevent?','a revolt against their officers','the ship’s normal arrival','a change in the weather','名词 mutiny 指船员反抗上级。',1),q('How did the crew mutiny in the second example?','they refused as a group to sail into danger','one sailor quietly checked a map','the captain ordered a new course','动词义是集体拒绝服从命令。',2),q('Which event is a mutiny?','soldiers collectively rebel against their commanding officers','one passenger misses a train','a captain changes the dinner menu','士兵集体反抗军官是叛变。',1,'meaning'),q('Mutiny is commonly associated with?','soldiers or sailors resisting their officers','a soft colour palette','the study of fungi','军队和船员反抗长官的情境常用 mutiny。',1,'context')]);
P('mutoscope','Mutoscope was coined for an early coin-operated motion-picture viewer that flipped a reel of photographs to create apparent movement.',C('mutoscope.s1','早期观影器','At the seaside arcade, visitors inserted a coin into a mutoscope and turned its handle to watch a short flickering scene.','在海滨游乐厅，游客投币后转动妙透镜的把手，观看一小段闪动的影像。','At the seaside arcade / visitors inserted a coin into a mutoscope / and turned its handle / to watch a short flickering scene.','mutoscope 作名词指投币式早期活动影像观看器，内部用连续照片模拟动作。','投币并转动把手，带动照片卷播放。','影像'),M('The arcade’s mutoscope streamed a digital film from a cloud server without any reel or moving photographs.','The arcade’s mutoscope showed motion by flipping a reel of photographs as the viewer turned a handle.','妙透镜以照片卷呈现动作，不是云端数字流媒体。','confusable'),[q('What did visitors insert into the mutoscope?','a coin','a film camera','a library card','这是投币式观影器。'),q('How did it make photographs appear to move?','it flipped a reel of pictures','it projected a live cloud video','it printed a single still image','连续照片快速翻动形成运动感。'),q('Which device is a mutoscope?','an early coin-operated viewer for short picture reels','a modern silent security camera','a musical instrument mute','mutoscope 是早期活动影像观看器。',1,'context'),q('What did a visitor turn to watch the scene?','the mutoscope’s handle','the camera’s lens','the radio dial','转动把手带动照片卷。',1,'meaning')]);
P('mutter','Mutter is an early 14th-century imitative word for low, indistinct speech; it can mean to speak unclearly, complain quietly, or the words themselves.',[C('mutter.s1','低声含糊说','The passenger muttered the platform number into his phone, so the ticket clerk asked him to repeat it clearly.','乘客对着手机含糊地低声说出站台号，售票员只好请他清楚地重复一遍。','The passenger muttered the platform number / into his phone / so the ticket clerk asked him / to repeat it clearly.','mutter 作动词可指低声、含混地说话。','售票员听不清数字，需要他重说。'),C('mutter.s2','小声抱怨','Workers muttered about the sudden rota change as they packed their tools after the late shift.','晚班结束收拾工具时，工人们小声抱怨突然更改的排班。','Workers muttered about the sudden rota change / as they packed their tools / after the late shift.','mutter about something 常指低声表达不满。','工人们在收工时私下抱怨。'),C('mutter.s3','含糊嘀咕声','A low mutter spread through the audience when the screen went dark halfway through the presentation.','演示到一半屏幕变黑时，观众席里响起一片低低的嘀咕声。','A low mutter spread through the audience / when the screen went dark / halfway through the presentation.','mutter 作名词指低沉、含糊的说话声或话语。','观众听见故障后发出的低语声。')],M('The passenger muttered the platform number so loudly and clearly that everyone heard it perfectly.','The passenger muttered the platform number so quietly that the clerk asked him to repeat it.','清晰响亮地说与 mutter 的低声含混相反。','meaning'),[q('Why did the clerk ask the passenger to repeat the number?','he had muttered it unclearly','he had shouted it across the station','the platform had moved','mutter 表示低声含糊说，可能听不清。',1),q('What were workers muttering about?','the sudden rota change','the colour of the screen','the platform’s construction','工人们小声抱怨排班突然改变。',2),q('In “a low mutter spread through the audience,” mutter is a?','noun for indistinct low speech','verb meaning to announce clearly','name of a ticket machine','此处指观众发出的低声嘀咕。',3,'grammar'),q('Which sound is a mutter?','quiet unclear words from a dissatisfied crowd','a loud alarm everyone can hear','a clear speech delivered to a hall','低沉含糊的低语是 mutter。',1,'context')]);
P('mutton','Mutton came through Old French moton from Medieval Latin multonem, probably from a Celtic word for “sheep”; it is meat from an adult sheep.',C('mutton.s1','羊肉食材','The stew uses mutton from an older sheep, simmered slowly with onions until the meat becomes tender.','这道炖菜用成年绵羊的羊肉与洋葱慢炖，直到肉质变嫩。','The stew uses mutton from an older sheep / simmered slowly with onions / until the meat becomes tender.','mutton 作不可数名词指成年绵羊的肉；幼羊肉通常称 lamb。','食材来自成年羊，而非 lamb。','饮食'),M('The menu called the meat mutton even though it came from a young lamb.','The menu called the meat lamb because it came from a young sheep.','mutton 指成年羊肉，幼羊肉通常称 lamb。','confusable'),[q('Which animal supplied the stew’s meat?','an adult sheep','a young lamb','a goat','mutton 指成年绵羊的肉。'),q('How was the mutton cooked?','slowly simmered with onions','served raw and frozen','baked inside a camera','慢炖洋葱让羊肉变嫩。'),q('Which menu item is mutton?','a dish made from adult sheep meat','a dish made from young lamb','a dish made from mushrooms','成年羊肉符合 mutton 的定义。',1,'meaning'),q('Mutton is usually used as?','an uncountable meat noun','a plural verb','a name for a young sheep','通常说 some mutton，不按个数计。',1,'countability')]);
P('mutual','Mutual came from Latin mutuus, “reciprocal or exchanged”; it describes feelings or actions returned by each side, or something shared.',[C('mutual.s1','彼此感情','After working together through a difficult project, the two researchers developed mutual respect for each other’s skills.','共同完成艰难项目后，两位研究人员彼此尊重对方的专业能力。','After working together through a difficult project / the two researchers developed mutual respect / for each other’s skills.','mutual 可形容双方彼此给予或感受到的情感、行动。','respect is felt by each researcher toward the other.','人际'),C('mutual.s2','共同拥有','The neighbours set up a mutual fund for repairing the shared well, with every household contributing the same amount.','邻居们设立了一个共同基金来维修共用水井，每户都缴纳相同金额。','The neighbours set up a mutual fund / for repairing the shared well / with every household contributing / the same amount.','mutual 也可表示由两人或多人共同拥有或承担。','基金由邻居们共同筹集。','社区')],M('The colleagues had mutual respect, but each admired only herself and neither respected the other.','The colleagues had mutual respect because each valued the other’s work.','只有单方面尊重不符合 mutual 表示彼此的含义。','meaning'),[q('What did the two researchers develop?','respect for each other’s skills','a fund owned by the city alone','a shared water well','双方都尊重对方的能力。',1),q('Who contributed to the mutual repair fund?','every neighbouring household','one outside company alone','the researchers’ laboratory','共同基金由各户平等出资。',2),q('A mutual agreement is?','accepted or shared by both sides','accepted by one person only','a private thought never communicated','mutual 表示双方共同或彼此的。',1,'meaning'),q('Which situation shows a mutual benefit?','both partner organisations gain from working together','one side gains while the other loses everything','neither side participates','双方都受益体现 mutual。',2,'context')]);
P('mutualism','Mutualism is mutual plus -ism; in ecology it is an interaction that benefits both partners, and in social thought a doctrine of mutual aid.',C('mutualism.s1','生态互惠','The ecologist described the relationship between the flowering plant and its pollinator as mutualism: each gained something from the exchange.','生态学家把开花植物与传粉者的关系称为互惠共生：双方都从这种交换中受益。','The ecologist described the relationship / between the flowering plant and its pollinator / as mutualism / each gained something from the exchange.','mutualism 作名词可指双方互相受益的生态关系，也指互助社会理论。','植物获得传粉，昆虫获得食物，双方皆受益。','生态'),M('The ecologist called the relationship mutualism even though one partner benefited while the other was consistently harmed.','The ecologist called the relationship mutualism because both partners benefited from it.','mutualism 的生态义要求双方互相受益。'),[q('What did the pollinator gain?','food from the flower','a new camera','control over the plant','传粉者从植物获取食物。'),q('What did the plant gain?','pollination','a winter coat','a shared bank account','植物从传粉者获得授粉。'),q('Ecological mutualism is an interaction in which?','both partners benefit','one partner always harms the other','neither partner affects the other','双方都获益是互惠共生的关键。',1,'meaning'),q('Which relationship is mutualism?','a fungus and plant each provide a benefit to the other','a parasite harms its host without helping it','two organisms never interact','双方都得到益处的生态关系属于 mutualism。',1,'context')]);
P('mutually','Mutually is mutual plus -ly and means reciprocally, by each side toward the other, or in common.',C('mutually.s1','相互同意','The two companies mutually agreed to extend the contract, so neither side had to accept the change alone.','两家公司相互同意延长合同，因此并非由任何一方单独接受这项变更。','The two companies mutually agreed / to extend the contract / so neither side / had to accept the change alone.','mutually 修饰 agreed，强调双方都同意。','合同变更由两家公司共同认可。'),M('The companies mutually agreed, meaning only one side accepted the change and the other objected.','The companies mutually agreed, meaning both sides accepted the change.','单方面接受不等于双方相互同意。','meaning'),[q('What did the companies agree to do?','extend the contract','cancel their partnership permanently','sell the pollinator','双方同意延长合同。'),q('How many sides accepted the change?','both companies','only one company','neither company','mutually agreed 指双方都同意。'),q('Mutually most nearly means?','reciprocally or by both sides','secretly and without agreement','one-sidedly','mutually 表示相互地、彼此地。',1,'meaning'),q('Which decision was made mutually?','both neighbours consented to share the repair cost','one neighbour imposed a cost on the other','the town decided without consulting anyone','双方共同同意体现 mutually。',1,'context')]);
P('my','My is the reduced form of mine used before a noun; as an interjection, “My!” expresses surprise.',[C('my.s1','所属关系','I left my notebook on the train, but the station staff found it and kept it at the information desk.','我把自己的笔记本落在火车上了，不过车站工作人员找到了它，并把它放在问讯处。','I left my notebook on the train / but the station staff found it / and kept it / at the information desk.','my 是限定词，放在名词前表示属于说话者。','my notebook 表示属于“我”的笔记本。'),C('my.s2','惊讶感叹','“My, that mountain is taller than it looked from the road,” Lena said as they reached the valley.','“哎呀，这座山比从公路上看起来高多了。”莉娜到达山谷时说道。','“My / that mountain is taller than it looked from the road” / Lena said / as they reached the valley.','My! 可作感叹词，表达惊讶或强调。','感叹句表达对山高的惊讶。')],M('Mila said “mine notebook” before the noun to show possession.','Mila said “my notebook” before the noun to show possession.','名词前用 my；mine 通常独立使用或作表语。','grammar'),[q('What did the speaker leave on the train?','her notebook','the train’s timetable','a mountain','my notebook 是说话人自己的笔记本。',1),q('Why did Lena say “My!”?','she was surprised by the mountain’s height','she was naming her notebook','she was giving an order','My! 在此表达惊讶。',2),q('Which phrase is grammatically correct?','my coat','mine coat','me coat','名词前应使用 my。',1,'grammar'),q('In “My, that is a tall mountain,” My functions as?','an interjection showing surprise','a possessive before a noun','a plural pronoun','My! 可作惊讶感叹词。',2,'meaning')]);
P('mycology','Mycology combines myco- (“fungus”) and -logy (“study”); it is the branch of biology concerned with fungi.',C('mycology.s1','生物学分支','In mycology class, students compared the structures of mushrooms, moulds, and yeasts under microscopes.','在真菌学课上，学生们用显微镜比较蘑菇、霉菌和酵母的结构。','In mycology class / students compared the structures / of mushrooms, moulds, and yeasts / under microscopes.','mycology 作不可数名词，指研究真菌的生物学分支。','课堂研究多种真菌的结构。','生物'),M('The course was called mycology even though it studied only planets and never examined fungi.','The course was called mycology because it studied mushrooms, moulds, and yeasts.','只研究行星而不研究真菌，不属于真菌学。','meaning'),[q('What did the students compare?','mushrooms, moulds, and yeasts','monarchies and parliaments','river currents and tides','这些都是 mycology 研究对象。'),q('Mycology is a branch of?','biology','astronomy','law','真菌学属于生物学。'),q('Which question belongs to mycology?','How do yeasts reproduce?','How do planets orbit a star?','How is a ship’s anchor designed?','酵母属于真菌学研究范围。',1,'context'),q('The element myco- refers to?','fungi or mushrooms','water','a single partner','myco- 指真菌或蘑菇。',1,'word-formation')]);
P('myopic','Myopic comes from myopia plus -ic; myopia is short-sightedness, and the word also describes narrow thinking focused only on the near term.',C('myopic.s1','视力近视','Without her glasses, the myopic runner could not read the distant trail marker until she was close to it.','这名近视的跑者不戴眼镜时，只有走近后才能看清远处的步道标志。','Without her glasses / the myopic runner could not read the distant trail marker / until she was close to it.','myopic 作形容词可指眼睛近视，也可比喻目光短浅。','远处标志看不清体现视力近视。','医学'),M('The doctor described the runner as myopic because she could read distant signs clearly but not nearby print.','The doctor described the runner as myopic because she struggled to see distant signs.','看近处困难、远处清楚是远视情形，不是近视。','confusable'),[q('What could the runner not read without glasses?','a distant trail marker','a nearby shoe label','the race number on her shirt','近视使她难以看清远处标志。'),q('What does myopic mean literally?','short-sighted','unable to hear','unable to taste','myopic 的字面义与近视有关。'),q('A myopic policy is likely to?','focus narrowly on immediate gains','consider long-term effects carefully','include many different viewpoints','比喻义指目光短浅、只看眼前。',1,'meaning'),q('Which is myopic in the figurative sense?','a plan that saves money now but creates larger costs next year','a plan balancing current needs and future effects','a clear view of distant mountains','只看眼前、忽视长期代价是短视。',1,'context')]);
P('myriad','Myriad came from Greek myrias, “ten thousand,” later also meaning a countless number; it can function as a noun or adjective.',C('myriad.s1','大量选择','The repair team considered a myriad of possible causes, from a loose wire to a faulty sensor.','维修团队考虑了无数种可能原因，从电线松动到传感器故障。','The repair team considered a myriad of possible causes / from a loose wire / to a faulty sensor.','a myriad of + 复数名词表示大量、数不胜数的事物；myriad 也可直接作形容词。','团队列出许多可能原因。'),M('The team faced a myriad of one possible cause.','The team faced a myriad of possible causes.','myriad 表示众多，后面应指许多原因而非仅一个。','grammar'),[q('How many possible causes did the team consider?','a very large number','exactly one','none at all','myriad 表示数量极多。'),q('Which causes were mentioned?','a loose wire and a faulty sensor','only a broken window','a cancelled meeting','这两项只是诸多可能原因的例子。'),q('Which phrase is natural?','a myriad of questions','a myriad question only','myriads of one question','常见搭配是 a myriad of + 复数名词。',1,'grammar'),q('Myriad originally referred to which number?','ten thousand','one hundred','one million','希腊 myrias 原指一万。',1,'word-formation')]);
P('myself','Myself is the reflexive or emphatic form of I, historically built from my and self.',[C('myself.s1','反身动作','I reminded myself to lock the laboratory door after the final sample had been stored.','最后一份样本存好后，我提醒自己锁上实验室的门。','I reminded myself / to lock the laboratory door / after the final sample / had been stored.','myself 作反身代词，指代句子主语 I。','提醒的对象与提醒者是同一个人。'),C('myself.s2','本人亲自','I myself checked every label before the boxes were sent to the museum.','箱子送往博物馆前，我本人逐一核对了每张标签。','I myself checked every label / before the boxes / were sent / to the museum.','myself 可作强调代词，强调说话者亲自完成动作。','myself 强调检查标签的是本人。')],M('I reminded me to lock the door after I had stored the final sample.','I reminded myself to lock the door after I had stored the final sample.','反身动词 remind 的宾语应与主语 I 对应，用 myself。','grammar'),[q('Whom did the speaker remind to lock the door?','the speaker herself','the museum visitors','the laboratory assistant only','myself 指回句子的主语 I。',1),q('Who checked every label in the second example?','the speaker personally','the museum’s guard','the delivery driver','I myself 强调说话者亲自检查。',2),q('Which sentence uses myself reflexively?','I taught myself to use the microscope.','Myself sent the package to the museum.','The sample checked myself.','反身代词 myself 回指主语 I。',1,'grammar'),q('Which sentence uses myself for emphasis?','I myself signed the final report.','I hurt myself on the ladder.','She spoke to myself.','I myself 突出“我本人”签字。',2,'meaning')]);
P('mysterious','Mysterious is based on Latin mysterium (“secret rite or hidden thing”) plus -ous; it means strange or secret, or difficult to explain.',[C('mysterious.s1','神秘现象','A mysterious blue light appeared above the lake after midnight, and no one nearby could identify its source.','午夜后湖面上方出现一道神秘蓝光，附近无人能确定它的来源。','A mysterious blue light appeared above the lake / after midnight / and no one nearby / could identify its source.','mysterious 可描述秘密、古怪而引人好奇的现象。','蓝光的来源无人知晓。'),C('mysterious.s2','难以理解','The manual’s mysterious final paragraph used unfamiliar abbreviations, leaving the repair crew unsure what to do.','说明书最后一段晦涩难懂，里面的缩写很陌生，维修人员不知该如何操作。','The manual’s mysterious final paragraph / used unfamiliar abbreviations / leaving the repair crew / unsure what to do.','mysterious 也可表示内容难以理解或解释。','陌生缩写使操作说明难以理解。')],M('The blue light was mysterious because everyone immediately identified its known source and explained it.','The blue light was mysterious because no one could identify its source.','来源已知且解释清楚的现象不再神秘。','meaning'),[q('What was mysterious above the lake?','a blue light of unknown source','a clearly labelled buoy','the morning ferry','湖上蓝光来源不明。',1),q('Why was the manual’s last paragraph hard to use?','it contained unfamiliar abbreviations','it gave a clear numbered procedure','it had no written words','陌生缩写让段落难懂。',2),q('Which event is mysterious?','a door opens with no known cause','a clock rings at its set time','a labelled switch turns on a lamp','原因不明的开门现象很神秘。',1,'context'),q('A mysterious instruction may be?','difficult to understand or explain','simple and perfectly clear','a repeated sound only','mysterious 也可形容难以理解的内容。',2,'meaning')]);
P('mysteriously','Mysteriously is mysterious plus -ly and means in a puzzling, secretive, or hard-to-explain way.',C('mysteriously.s1','原因不明地','The sealed archive box mysteriously appeared in the reading room, although the sign-out log showed no one had borrowed it.','密封档案箱不知为何出现在阅览室，尽管借阅记录显示无人借走它。','The sealed archive box mysteriously appeared / in the reading room / although the sign-out log showed / no one had borrowed it.','mysteriously 是副词，修饰 appeared，表示出现的方式或原因令人费解。','记录与档案箱出现地点相矛盾，原因不明。'),M('The box mysteriously appeared because the staff had clearly tracked its delivery and recorded every step.','The box mysteriously appeared even though no one could explain how it reached the room.','有完整明确的运送记录就不算原因不明。'),[q('Where did the archive box appear?','in the reading room','in the loading bay','inside a ship’s cabin','档案箱出现在阅览室。'),q('Why was its appearance mysterious?','the log showed nobody had borrowed it','the delivery had been openly announced','the box was clearly labelled','借阅记录无法解释箱子出现。'),q('Mysteriously modifies which action?','appeared','showed','borrowed','副词描述箱子出现的方式。',1,'grammar'),q('Which event happened mysteriously?','a missing key turns up in a locked room with no explanation','a clerk returns a key on schedule','a visitor signs out a key','无人解释的钥匙出现方式令人费解。',1,'context')]);
P('mystery','Mystery came through French from Latin mysterium and Greek mystērion, a secret rite or hidden thing; it can mean a puzzle, an air of secrecy, or a crime-solving story.',[C('mystery.s1','未解之谜','The sudden drop in river temperature remains a mystery because sensors found no leak or change in the upstream flow.','河水温度突然下降仍是个谜，因为传感器没有发现泄漏或上游流量变化。','The sudden drop in river temperature remains a mystery / because sensors found no leak / or change in the upstream flow.','mystery 作名词可指原因或解释尚不清楚的事物。','现有监测无法解释水温突降。'),C('mystery.s2','神秘氛围','The old observatory’s locked dome and silent corridors gave the building an air of mystery.','旧天文台上锁的圆顶和寂静的走廊，让整座建筑带有神秘感。','The old observatory’s locked dome and silent corridors / gave the building / an air of mystery.','mystery 也可指神秘、难以捉摸的性质或氛围。','建筑的封闭与寂静营造神秘感。'),C('mystery.s3','侦探小说','On the train, Farah read a mystery in which a detective searched a country house for the missing necklace.','火车上，法拉读了一本悬疑小说，故事中的侦探在乡间宅邸寻找失踪的项链。','On the train / Farah read a mystery / in which a detective searched a country house / for the missing necklace.','mystery 作名词也指围绕犯罪或谜案展开的故事类型。','侦探寻找失窃项链是悬疑故事。','文学')],M('The temperature drop was no mystery because sensors identified the broken pipe immediately.','The temperature drop remained a mystery because the sensors found no cause.','原因已被传感器确定，就不再是未解之谜。'),[q('Why did the river temperature drop remain a mystery?','the sensors found no cause','the sensors located a clear leak','the river had never been monitored','传感器未找到水温下降的原因。',1),q('What gave the observatory an air of mystery?','its locked dome and silent corridors','its bright open doors and guided tours','its noisy market stalls','封闭、寂静营造了神秘氛围。',2),q('What is Farah reading on the train?','a detective story about a missing necklace','a weather report about the river','a manual for an observatory','mystery 可指侦探悬疑作品。',3,'meaning'),q('Which phrase names the quality of being hard to explain?','the mystery of the sudden temperature drop','a mystery about a detective','a mysterious-looking dome','此处 mystery 指未解之谜本身。',1,'context')]);
P('mystical','Mystical came through Old French and Latin from Greek mystikos, “secret or connected with sacred mysteries”; it describes the inexplicable or spiritual experience.',[C('mystical.s1','奇异难解','The hikers described the glowing mist in the forest as mystical, though the ranger later traced it to a nearby marsh.','徒步者把森林里发光的雾描述得如梦似幻，尽管护林员后来查明那是附近沼泽造成的。','The hikers described the glowing mist / in the forest as mystical / though the ranger later traced it / to a nearby marsh.','mystical 可形容奇异、难以解释而带有神秘感的事物。','徒步者当时无法解释发光雾。'),C('mystical.s2','神秘体验','The memoir recounts a mystical experience during which the writer felt spiritually connected to all living things.','回忆录讲述了作者的一次神秘体验；当时他觉得自己在精神上与所有生命相连。','The memoir recounts a mystical experience / during which the writer felt spiritually connected / to all living things.','mystical 也可表示与神秘主义或直接精神体验有关。','作者描述的是精神层面的体验。','宗教')],M('The memoir called the experience mystical but explained it only as an ordinary bus timetable with no spiritual or unusual element.','The memoir called the experience mystical because the writer described an intense spiritual connection.','纯粹普通的时刻表没有神秘或精神体验含义。','meaning'),[q('What caused the glowing mist?','a nearby marsh','a broken camera','a monastery bell','护林员把雾追溯到附近沼泽。',1),q('What did the writer feel during the mystical experience?','spiritually connected to living things','unable to read a train ticket','angry about a contract','回忆录写到精神上的联系。',2),q('A mystical experience is associated with?','a direct spiritual or profound mysterious experience','a routine market price calculation','a clear weather forecast','该义项与精神体验有关。',2,'meaning'),q('Which scene seems mystical in the general sense?','an unexplained light moving silently through a forest','a labelled lamp switched on by a timer','a clerk reading a clear instruction','不明光影带来奇异神秘感。',1,'context')]);
P('mystify','Mystify came through French mystifier, formed from mystique (“mysterious”) plus -fier (“make”); it means to confuse someone or make something seem mysterious.',[C('mystify.s1','使人困惑','The technician’s explanation mystified the audience because it introduced three new acronyms without defining any of them.','技术员的解释让听众一头雾水，因为他引入了三个新缩写却一个也没定义。','The technician’s explanation mystified the audience / because it introduced three new acronyms / without defining any of them.','mystify 作及物动词表示使人困惑、难以理解。','听众无法理解未解释的缩写。'),C('mystify.s2','蒙上神秘色彩','The tour guide mystified the old lighthouse by telling an unverified ghost story instead of explaining its working parts.','导游没有讲解旧灯塔的工作部件，反而讲了未经证实的鬼故事，把它说得神秘莫测。','The tour guide mystified the old lighthouse / by telling an unverified ghost story / instead of explaining its working parts.','mystify 也可指故意把某事描述得神秘、难以解释。','鬼故事让灯塔显得神秘。','叙事')],M('The instructions mystified nobody because every new term was defined in plain language.','The instructions mystified the new staff because they used unfamiliar terms without explanation.','通俗解释所有术语不会使读者困惑。','meaning'),[q('Why was the audience mystified?','the acronyms were not explained','the technician defined every term','the talk contained no technical words','未解释的缩写让听众困惑。',1),q('How did the guide mystify the lighthouse?','by telling an unverified ghost story','by explaining the lamp mechanism clearly','by publishing its maintenance plan','鬼故事给灯塔蒙上神秘色彩。',2),q('To mystify someone is to?','confuse them or make something seem mysterious','give them a clear step-by-step answer','invite them to a shared fund','mystify 有使困惑或神秘化之义。',1,'meaning'),q('Which guide would mystify visitors?','one who replaces a clear history with unexplained legends','one who explains each feature plainly','one who answers every question directly','用未解释的传说取代清晰说明会造成神秘感。',2,'context')]);

(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('mystique','Mystique came through French mystique from Latin mysticus; in English it means an appealing air of mystery or special significance.',C('mystique.s1','神秘魅力','The remote observatory’s mystique attracted visitors, who imagined secret discoveries behind its locked dome.','偏远天文台的神秘魅力吸引了游客，他们想象着上锁圆顶后藏有秘密发现。','The remote observatory’s mystique attracted visitors / who imagined secret discoveries / behind its locked dome.','mystique 作名词表示因不完全了解而令人着迷的神秘氛围。','游客被未知秘密所吸引。'),M('The observatory’s mystique vanished when its mysterious reputation was replaced by a clear, ordinary guide to every room.','The observatory’s mystique drew visitors who were intrigued by what remained unexplained.','所有情况都已清楚解释时，神秘氛围便不再吸引人。','meaning'),[q('What attracted visitors to the observatory?','its air of mystery','its public swimming pool','its easy access to every room','未知的秘密感吸引游客。'),q('What did visitors imagine?','secret discoveries behind the dome','a new mutton recipe','a ship’s mutiny','他们想象圆顶后藏着秘密发现。'),q('Mystique most nearly means?','an appealing aura of mystery','a confusing instruction only','a religious community’s residence','mystique 指迷人的神秘光环。',1,'meaning'),q('Which place has mystique?','an old archive surrounded by intriguing unanswered questions','a fully documented storage room with nothing concealed','a bright noticeboard listing every fact','未解之处会带来 mystique。',1,'context')]);
P('myth','Myth came from Greek mythos, “story or discourse,” through Latin and French; its ultimate origin is unknown. It can name a traditional sacred story or a widely believed false idea.',[C('myth.s1','传统故事','The myth explains why the ancient villagers believed thunder was the sound of a god’s chariot crossing the sky.','这个神话解释了古代村民为何相信雷声是神的战车驶过天空所发出的声音。','The myth explains / why the ancient villagers believed / thunder was the sound / of a god’s chariot crossing the sky.','myth 作名词可指用神祇或英雄故事解释世界的传统神话。','故事以神祇解释自然现象。'),C('myth.s2','错误观念','It is a myth that goldfish remember events for only three seconds; research shows they can learn and retain information.','金鱼的记忆只有三秒钟是个错误观念；研究表明它们能够学习并保留信息。','It is a myth / that goldfish remember events for only three seconds / research shows / they can learn and retain information.','myth 也可指许多人相信但并不真实的说法。','研究证据否定了广为流传的说法。')],M('The belief that goldfish remember for only three seconds is a myth, and scientists have proved that this claim is true.','The belief is a myth because research shows goldfish can retain information longer than three seconds.','一项已被证伪的观念不能同时被说成已获证实。','meaning'),[q('What did the ancient myth explain?','the supposed divine cause of thunder','how fish retain information','why a ship’s crew rebelled','神话把雷声解释为神的战车。',1),q('Why is the goldfish claim called a myth?','evidence shows the claim is false','research confirms exactly three seconds','no one has studied goldfish','广为人知但错误的说法也叫 myth。',2),q('Which is a myth in the false-belief sense?','a common claim contradicted by evidence','a documented event confirmed by records','a scientific measurement','错误观念义指广传却不真的看法。',2,'meaning'),q('A myth about thunder is usually?','a traditional story explaining nature through gods or heroes','a technical manual for a microscope','a report of a present-day experiment','传统神话常借神祇或英雄解释世界。',1,'context')]);
P('mythical','Mythical is myth plus -ical and means belonging to a myth or existing only in legend rather than in fact.',C('mythical.s1','传说生物','The museum’s guide explained that the dragon on the banner was a mythical creature, not an animal known to science.','博物馆讲解员说明，旗帜上的龙是神话生物，并非科学界已知的动物。','The museum’s guide explained / that the dragon on the banner was a mythical creature / not an animal / known to science.','mythical 作形容词描述来自神话或现实中并不存在的事物。','龙属于传说，不是已知动物。','文学'),M('The guide called the mythical dragon a common living animal that scientists routinely observe in the wild.','The guide called the dragon mythical because it belongs to legend, not known zoology.','已知且常见的野生动物不是只存在于神话中的生物。'),[q('What was shown on the museum banner?','a dragon from legend','a documented local bird','a real laboratory mouse','龙是神话生物。'),q('Does science know the dragon as a real animal?','no, it belongs to legend','yes, it is routinely observed','yes, it is a species of fish','例句明确说它不是科学界已知动物。'),q('A mythical kingdom is?','one found in stories, not verified history','a current country with a government','a scientific laboratory','mythical 可表示只存在于神话或传说。',1,'meaning'),q('Mythical is formed from myth plus?','-ical','-ist','-ize','-ical 构成形容词 mythical。',1,'word-formation')]);
P('mythological','Mythological combines myth with -ological and means relating to traditional stories about gods, heroes, and origins.',C('mythological.s1','神话题材','The exhibition pairs a mythological map of the underworld with notes explaining how different Greek stories describe the journey of the dead.','展览把一幅神话中的冥界地图与说明并列，解释不同希腊故事如何描绘亡者的旅程。','The exhibition pairs a mythological map / of the underworld / with notes explaining / how different Greek stories describe the journey of the dead.','mythological 作形容词，修饰与神话故事有关的角色、地点或主题。','地图呈现希腊神话中的冥界。','艺术'),M('The catalogue called the underworld map mythological, although it showed a surveyed modern subway system with no connection to myth.','The catalogue called the underworld map mythological because it depicts a place from Greek stories.','现代地铁测绘图不是神话题材。','meaning'),[q('What place does the exhibition map depict?','the underworld in Greek stories','a modern subway network','a monastery garden','地图展示神话中的冥界。'),q('What does mythological mean?','relating to myths about gods or heroes','relating to modern train schedules','relating to a real insect species','mythological 指与神话相关。'),q('Which exhibit is mythological?','a vase painted with the labours of Heracles','a city map showing current bus stops','a medical chart of blood pressure','希腊英雄故事属于神话题材。',1,'context'),q('Mythological is most closely related to?','myth','mutual','nadir','mythological 描述 myth 的相关内容。',1,'word-formation')]);
P('mythology','Mythology comes through Late Latin from Greek mythologia, “telling of myths”; it can mean a body of traditional stories or one culture’s set of such stories.',[C('mythology.s1','神话总称','The course studies mythology by comparing creation stories, heroic journeys, and flood legends from several ancient societies.','这门课程通过比较多个古代社会的创世故事、英雄旅程和洪水传说来研究神话。','The course studies mythology / by comparing creation stories / heroic journeys / and flood legends from several ancient societies.','mythology 可泛指解释自然或历史的古代神话故事。','课程比较不同社会的多类神话。','学术'),C('mythology.s2','文化体系','Norse mythology includes stories about Odin, Thor, and the world tree, forming a body of tales associated with one culture.','北欧神话包括奥丁、索尔和世界树的故事，构成与一种文化相关的一套传说。','Norse mythology includes stories about Odin and Thor / and the world tree / forming a body of tales / associated with one culture.','mythology 也可指某一文化所拥有的一套神话。','例句聚焦北欧这一文化体系。','文化')],M('The course described Norse mythology as one story unrelated to any other traditional tale.','The course described Norse mythology as a connected body of traditional stories from Norse culture.','mythology 可指一套故事，而非仅一则彼此无关的故事。'),[q('What kinds of stories does the course compare?','creation stories, heroic journeys, and flood legends','modern detective novels only','laboratory reports on fungi','课程通过多种传统故事研究 mythology。',1),q('Whose mythology includes Odin and Thor?','Norse culture’s','ancient Greek culture’s only','a modern company’s','Odin 和 Thor 属于北欧神话体系。',2),q('Mythology can mean?','traditional stories collectively or a culture’s story system','one true news report','a single measurement unit','mythology 可指神话总称或特定文化的一套神话。',1,'meaning'),q('A scholar comparing Greek and Norse myths studies?','mythology','mutualism','monochrome','不同文化的神话属于 mythology 研究。',1,'context')]);
P('myxoma','Myxoma is a medical term formed from Greek myxa (“mucus”) and -oma (“tumour”); it names a usually benign growth of mucoid connective tissue.',C('myxoma.s1','医学术语','The radiology report noted a possible myxoma near the heart, and the patient was referred for specialist assessment.','影像报告指出心脏附近可能有黏液瘤，患者随后被转诊接受专科评估。','The radiology report noted a possible myxoma / near the heart / and the patient was referred / for specialist assessment.','myxoma 作名词指黏液样结缔组织生长形成的肿瘤，通常为良性。','报告将其作为待评估的可能诊断，而非确诊。','医学'),M('The report diagnosed a myxoma as a bacterial infection that could be treated with antibiotics alone.','The report described a myxoma as a growth of mucoid connective tissue requiring specialist assessment.','myxoma 指组织生长，不是细菌感染。','confusable'),[q('What did the report note near the heart?','a possible myxoma','a broken rib','a fungal culture','报告提示可能有黏液瘤。'),q('What happened next?','the patient was referred for specialist assessment','the report said no review was needed','the patient returned to the river','影像报告后建议专科评估。'),q('Myxoma is a growth involving?','mucoid connective tissue','a group of sea mammals','a single oxygen atom','myxoma 是黏液样组织肿瘤。',1,'meaning'),q('Which statement is safest and accurate?','a suspected myxoma should be assessed by a clinician','every myxoma is certainly malignant','a myxoma is an ordinary muscle cramp','医学报告提到可能病变，应交由临床专科评估。',1,'context')]);
P('nadir','Nadir came through Medieval Latin from Arabic naẓīr as-samt, “opposite direction”; astronomy uses it for the point opposite the zenith, and figuratively it means a lowest point.',C('nadir.s1','最低阶段','After a year of cancelled contracts, the theatre’s finances reached their nadir before a successful fundraising campaign began.','一年合同接连取消后，剧院财务跌至最低点，之后才启动了一场成功的筹款活动。','After a year of cancelled contracts / the theatre’s finances reached their nadir / before a successful fundraising campaign began.','nadir 作名词指某种状况所达到的最低点。','筹款之前财务状态最差。'),M('The report called the company’s nadir the highest profit it had ever earned.','The report called the year of heavy losses the company’s nadir.','nadir 表示最低点，不是最高利润。','confusable'),[q('When did the theatre’s finances reach their nadir?','after a year of cancelled contracts','after the successful fundraiser','before the theatre opened','大量合同取消后财务跌至最低点。'),q('Nadir most nearly means?','the lowest point','the highest point','a shared agreement','nadir 的比喻义是最低点。'),q('In astronomy, the nadir is?','the point in the sky opposite the zenith','the point directly overhead','the North Star','nadir 与天顶相对。',1,'meaning'),q('Which sentence uses nadir figuratively?','Her confidence reached its nadir after the failed audition.','The bird reached the top of the tree.','The astronomer recorded the zenith.','信心跌至最低处是比喻用法。',1,'context')]);
P('nag','Nag as a verb probably comes from a Scandinavian word related to “gnaw”; it means to keep finding fault or pressing someone with repeated complaints.',C('nag.s1','反复催促','Rather than nag her colleague all afternoon, Priya sent one clear reminder about the overdue safety form.','普里娅没有整个下午反复催同事，而是清楚地提醒了一次逾期未交的安全表格。','Rather than nag her colleague all afternoon / Priya sent one clear reminder / about the overdue safety form.','nag 作动词表示不断抱怨或催促，常含令人厌烦的语气。','一次明确提醒与反复催促形成对比。','人际'),M('Priya nagged her colleague by sending one polite message and never mentioning the form again.','Priya nagged her colleague by repeatedly complaining about the overdue form.','只提醒一次而不再提及，不是反复唠叨。','meaning'),[q('What did Priya do instead of nagging?','sent one clear reminder','repeated the complaint all afternoon','cancelled the form','她只发了一次清楚提醒。'),q('Nagging usually involves?','repeated complaints or pressure','one neutral announcement','a single silent gesture','nag 强调令人厌烦的反复催促。'),q('Which behaviour is nagging?','asking someone again and again to clean the shared kitchen','making one polite request and accepting the answer','quietly completing your own task','反复催促属于 nag。',1,'context'),q('Nag is used here as a?','verb describing repeated pressure','noun meaning a metal fastener','adjective meaning naked','例句中 nag 是动词。',1,'grammar')]);
P('nail','Nail is from Old English negel or nægl, from Proto-Germanic *naglaz; the same inherited word names a fingernail and a pointed metal fastener.',[C('nail.s1','手指甲','The nurse checked the patient’s fingernail for a pale line and recorded the observation in the chart.','护士检查了病人的手指甲是否有浅色线条，并把观察结果记入病历。','The nurse checked the patient’s fingernail / for a pale line / and recorded the observation / in the chart.','nail 作名词可指手指或脚趾末端的硬甲板。','nail 位于指尖，护士检查其外观。','医学'),C('nail.s2','金属钉子','A carpenter chose a short nail with a flat head to secure the loose trim without splitting the wood.','木匠选了一枚短平头钉，把松动的饰条固定好，同时避免木材开裂。','A carpenter chose a short nail / with a flat head / to secure the loose trim / without splitting the wood.','nail 作名词也指带平头的细长金属钉。','平头钉穿过饰条固定木件。','工具'),C('nail.s3','用钉固定','They nailed the notice to the wooden gate so that visitors could see the new opening hours.','他们把告示钉在木门上，好让访客看到新的开放时间。','They nailed the notice to the wooden gate / so that visitors could see / the new opening hours.','nail 作及物动词表示用钉子把物件固定到表面。','notice 是被钉到门上的物件。','工具'),C('nail.s4','抓获并证实','Investigators nailed the contractor for falsifying invoices after matching the altered records to bank transfers.','调查人员把篡改记录与银行转账核对后，抓住了承包商伪造发票的证据。','Investigators nailed the contractor / for falsifying invoices / after matching the altered records / to bank transfers.','口语中 nail someone for something 可表示抓到某人做某事并有明确证据。','账目与转账记录相互印证，坐实伪造发票。','法律')],M('The carpenter nailed the trim by placing a loose screw beside it without attaching the pieces.','The carpenter nailed the trim by driving a metal nail through it into the wood.','把螺丝放在旁边没有用钉子固定饰条。','meaning'),[q('What did the nurse examine?','the hard plate on the patient’s finger','the wooden gate','the contractor’s invoice','指甲是手指末端的硬甲板。',1),q('What fastener did the carpenter choose?','a short flat-headed metal nail','a soft piece of cloth','a microscope lens','平头金属钉用于固定饰条。',2),q('What did they nail to the gate?','a notice','a fingernail','a bank transfer','动词 nail 表示把告示钉在门上。',3,'grammar'),q('Why did investigators nail the contractor?','they found evidence of falsified invoices','they fitted a metal spike into wood','they checked the contractor’s fingernails','口语义指抓到并有证据证明其过错。',4,'meaning')]);
P('naive','Naive came through French naïve from Latin nativus, “natural or inborn”; it can mean inexperienced and trusting, or artless and untrained in style.',[C('naive.s1','缺乏经验','It was naive of the new buyer to send the deposit before checking whether the seller actually owned the equipment.','新买家未经核实卖家是否真拥有设备便先付定金，这样做缺乏经验。','It was naive of the new buyer / to send the deposit / before checking / whether the seller actually owned the equipment.','naive 可形容经验不足、容易轻信的人或判断。','未核实所有权便付款体现轻信。'),C('naive.s2','朴拙风格','The painter’s naive style uses simple shapes and direct colours rather than academic perspective or polished technique.','这位画家的朴拙风格使用简单形状和直接色彩，而非学院派透视或精致技巧。','The painter’s naive style uses simple shapes and direct colours / rather than academic perspective / or polished technique.','naive 描述艺术风格时可指未经正规训练、质朴自然而非人工雕琢。','画面简单直接，不追求学院技巧。','艺术')],M('The buyer was naive to trust the offer, meaning she carefully verified the seller and every document first.','The buyer was naive to trust the offer without checking ownership or documents.','仔细核实后再相信并非缺乏经验地轻信。','meaning'),[q('What did the buyer fail to check?','whether the seller owned the equipment','the equipment’s colour only','the buyer’s own address','未核实所有权就付款显得轻信。',1),q('What gives the painter’s style a naive quality?','simple shapes and unpolished technique','careful academic perspective','photographic realism','朴拙风格不依赖精细学院技巧。',2),q('Which person is naive in the trusting sense?','someone who believes a stranger’s promise without checking it','someone who verifies the contract carefully','someone experienced in negotiation','轻信陌生人的承诺是缺乏经验。',1,'meaning'),q('A naive painting may be?','simple and self-taught in style','technically polished in academic perspective','a literal photograph','naive 的艺术义指质朴、未受训练的风格。',2,'context')]);
P('naive artist','Naive artist combines naive with artist; the art term describes a painter working in a simple, self-taught style.',C('naive artist.s1','艺术类型','The exhibition labels Mara a naive artist because she developed a direct, self-taught style outside formal art schools.','展览把玛拉称为素朴画家，因为她在正规艺术院校之外形成了直接、未经学院训练的风格。','The exhibition labels Mara a naive artist / because she developed a direct, self-taught style / outside formal art schools.','naive artist 作名词短语，指以朴素自学风格创作的艺术家；不等于缺乏智力。','例句关注绘画训练和风格，而非智力判断。','艺术'),M('The catalogue called Mara a naive artist because she followed advanced academic training and copied a polished realist technique exactly.','The catalogue called Mara a naive artist because her simple style was self-taught and outside formal training.','严格学院训练和精细写实技法与此处的 naive artist 风格不符。','word-choice'),[q('Why does the exhibition call Mara a naive artist?','her direct style developed outside formal art schools','she paints only mythological subjects','she has never shown her work','标签指自学形成的朴素风格。'),q('Naive artist is an art term for?','an artist with a simple, self-taught style','an artist who is necessarily unintelligent','an artist who paints only children','该词组指素朴自学风格的画家。'),q('Which painter best fits the term?','a self-taught painter using direct, simple forms','a formally trained painter specialising in exact academic realism','a museum guard who does not paint','自学且风格朴素符合该术语。',1,'context'),q('Does naive artist mean the painter lacks intelligence?','no; it describes an art style and training','yes, it is a diagnosis','yes, it means the painter cannot learn','在艺术术语里关注风格，不是智力评价。',1,'meaning')]);
P('naked','Naked comes from Old English nacod, from Proto-Germanic *nakwadaz and an ancient root meaning “naked”; it describes an unclothed person, an uncovered thing, or unaided vision.',[C('naked.s1','未穿衣物','The swimmer reached the changing room wrapped in a towel after leaving the pool naked.','游泳者离开泳池时没有穿衣服，裹着毛巾走到了更衣室。','The swimmer reached the changing room / wrapped in a towel / after leaving the pool naked.','naked 可指没有穿衣物；例句语境保持中性，不作细节描写。','泳池后裹毛巾前往更衣室。'),C('naked.s2','没有遮护','The cable lay naked across the floor, so the electrician covered it before anyone could trip or touch it.','电缆裸露地横在地板上，电工在有人绊倒或触碰前把它遮护起来。','The cable lay naked across the floor / so the electrician covered it / before anyone could trip or touch it.','naked 也可形容物品没有通常的外层覆盖或保护。','电缆外露需要加以保护。','安全'),C('naked.s3','肉眼可见','The pale planet was visible to the naked eye once the clouds moved away from the horizon.','云层从地平线散去后，那颗浅色行星便能用肉眼看见。','The pale planet was visible to the naked eye / once the clouds moved away / from the horizon.','the naked eye 指不借助望远镜、显微镜等仪器的肉眼。','行星可以不用光学仪器直接观察。','天文')],M('The planet was visible to the naked eye only through a powerful telescope.','The planet was visible to the naked eye without a telescope.','依靠强力望远镜观察不属于裸眼观看。','meaning'),[q('What was the swimmer wearing after leaving the pool?','a towel','a lab coat','a metal nail','游泳者裹着毛巾前往更衣室。',1),q('Why did the electrician cover the cable?','it was exposed and could be touched or tripped over','it was already protected inside a wall','it had no electrical current','裸露电缆可能造成触碰或绊倒危险。',2),q('To see a planet with the naked eye means?','to see it without an optical aid','to use a telescope','to view it in a photograph only','naked eye 是不借助仪器的肉眼。',3,'meaning'),q('Which object is naked in the “uncovered” sense?','a wire with its protective casing removed','a wire sealed inside insulation','a planet in the sky','缺少保护层的电线可称 naked。',2,'context')]);
P('name','Name is from Old English nama, from Proto-Germanic *naman-; it can identify someone or something, refer to reputation, or mean to give, state, or appoint a name.',[C('name.s1','名称','The name of the research vessel, Aurora, was painted in large letters on both sides of its bow.','这艘研究船名为“极光号”，船首两侧都漆着醒目的大字。','The name of the research vessel / Aurora / was painted / on both sides of its bow.','name 作名词指人、地点或事物被称呼的词。','Aurora 是船的名称。'),C('name.s2','名声','The restaurant has a good name among local families because it serves reliable meals at fair prices.','这家餐馆在当地家庭中口碑很好，因为它提供价格公道、品质稳定的餐食。','The restaurant has a good name / among local families / because it serves reliable meals / at fair prices.','name 也可指某人或企业在人们心中的名声、评价。','顾客评价形成餐馆的口碑。'),C('name.s3','给取名字','They named the rescued seal Juniper after the tree that stood beside the rehabilitation pool.','他们用康复池旁的一棵树为获救的海豹取名“杜松”。','They named the rescued seal Juniper / after the tree / that stood beside the rehabilitation pool.','name 作及物动词可表示给人或事物取名，结构为 name + 宾语 + 名称。','Juniper 是被命名的海豹的新名字。'),C('name.s4','说出或任命','The committee named Dr Chen as the new chair after reviewing the candidates’ experience.','委员会审查候选人的经验后，任命陈博士为新主席。','The committee named Dr Chen / as the new chair / after reviewing / the candidates’ experience.','name 还可表示说出某人或某物的身份，或正式任命某人担任职务。','named Dr Chen as chair 表示任命。','职场')],M('The committee named Dr Chen the new chair, but stated that she had not been selected for the post.','The committee named Dr Chen as the new chair after selecting her for the post.','name someone as 表示说出或任命其身份，与否认其获任相矛盾。','meaning'),[q('What name was painted on the vessel?','Aurora','Juniper','Chen','Aurora 是研究船的名称。',1),q('Why does the restaurant have a good name?','local families trust its reliable food and fair prices','it was named after a tree','it has no known reputation','good name 指良好口碑。',2),q('What did the rescuers name the seal?','Juniper','Aurora','Dr Chen','动词 named 后接取的名字 Juniper。',3,'grammar'),q('What did the committee do when it named Dr Chen as chair?','appointed her to the role','gave her a vessel’s name','criticised the restaurant','此处 name 表示任命职务。',4,'meaning')]);
P('named','Named is the past participle of name and means given a particular name or identified with that name.',C('named.s1','被命名者','The newly discovered comet, named after the observatory, will be visible through small telescopes next month.','这颗以天文台命名的新发现彗星，下个月可用小型望远镜观测。','The newly discovered comet / named after the observatory / will be visible / through small telescopes next month.','named 作过去分词形容词修饰 comet，表示它被赋予了特定名称。','after the observatory 说明名称来源。','天文'),M('The comet was named after the observatory, but no one had given it any name.','The comet was named after the observatory, which supplied its name.','被命名的对象已经有名称，不是没有名字。'),[q('What was the comet named after?','the observatory','the telescope lens','the research vessel’s captain','彗星的名字取自天文台。'),q('What does named mean in the sentence?','given a particular name','made impossible to see','appointed as a committee chair','named 表示已被取名。'),q('Which phrase uses named correctly?','a village named after a river','a river named before it had any name','a village names after a river','named after 是“以……命名”。',1,'grammar'),q('What can named modify?','a person or thing that has been given a name','only a past-tense verb','only an adjective of colour','named 可作过去分词形容词修饰名词。',1,'context')]);
P('namely','Namely is name plus -ly; it introduces a precise item or clarifies exactly which case is meant.',[C('namely.s1','具体列举','Three documents were missing, namely the permit, the invoice, and the signed inspection sheet.','有三份文件缺失，即许可证、发票和签字的检查表。','Three documents were missing / namely the permit / the invoice / and the signed inspection sheet.','namely 可用于引出对前面概括内容的具体说明或列举。','冒号式列举说明“三份文件”具体所指。'),C('namely.s2','限定对象','Only one applicant, namely the engineer with a current safety certificate, may enter the restricted room.','只有一名申请人可以进入限制区域，也就是持有有效安全证书的那位工程师。','Only one applicant / namely the engineer with a current safety certificate / may enter / the restricted room.','namely 也可限定说明特指哪一个对象，而不是其他情况。','句子限定为持有效证书的那一位工程师。')],M('Three documents were missing, namely no documents at all.','Three documents were missing, namely the permit, invoice, and signed inspection sheet.','namely 后应说明所指的具体文件，而不是与数量相反的“零份”。','meaning'),[q('Which items were missing?','the permit, invoice, and inspection sheet','three safety certificates','the engineer’s tools','namely 后列出缺失文件。',1),q('Who may enter the restricted room?','the engineer with a current safety certificate','every applicant without qualification','the three document suppliers','namely 限定为持有效证书的工程师。',2),q('What does namely usually introduce?','the precise item or case just mentioned','a contrast with the previous statement','an uncertain possibility only','namely 用来具体说明前文。',1,'meaning'),q('Which punctuation can introduce a clarification with namely?','a comma, as in “one issue, namely the missing key”','an apostrophe inside the word','a question mark inside the word','namely 常接在逗号后引出说明。',1,'grammar')]);
P('nanometer','Nanometer combines nano- (“one billionth”) with meter, the unit of length; one nanometer is 10⁻⁹ meter.',C('nanometer.s1','微观尺度','A DNA strand is only a few nanometers wide, far too small to measure with a ruler.','DNA 链的宽度只有几纳米，小到无法用普通尺子测量。','A DNA strand is only a few nanometers wide / far too small / to measure / with a ruler.','nanometer 作长度单位，等于十亿分之一米；其符号为 nm。','DNA 分子尺度远小于普通尺子刻度。','测量'),M('The instrument reported a nanometer as one billion meters long.','The instrument reported a nanometer as one billionth of a meter.','nano- 表示十亿分之一，而不是十亿倍。','measurement'),[q('How wide was the DNA strand?','a few nanometers','several kilometres','a few metres','DNA 链只有几纳米宽。'),q('What is one nanometer?','one billionth of a meter','one billion meters','one million kilometres','nm 对应 10⁻⁹ 米。'),q('Which object needs a nanometer scale?','a tiny molecular structure','a city street','a mountain range','分子结构适合用纳米尺度描述。',1,'context'),q('What is the common symbol for nanometer?','nm','km','mm','nanometer 的单位符号是 nm。',1,'measurement')]);
P('nap','Nap has separate histories: the short-sleep verb comes from Old English hnappian, of uncertain origin; the cloth sense comes from Middle Dutch or Middle Low German noppe.',[C('nap.s1','短时睡眠','After the night shift, Luis took a short nap before driving home, setting an alarm so he would not oversleep.','夜班后，路易斯开车回家前先小睡了一会儿，并设了闹钟避免睡过头。','After the night shift / Luis took a short nap / before driving home / setting an alarm so he would not oversleep.','nap 作名词指白天或短时间的小睡。','这段睡眠发生在夜班后且时间不长。'),C('nap.s2','织物绒面','The tailor brushed the coat’s nap in one direction so the fabric would reflect light evenly.','裁缝顺着一个方向刷理外套的绒面，让布料均匀反光。','The tailor brushed the coat’s nap in one direction / so the fabric / would reflect light / evenly.','nap 作名词还指某些布料表面短而柔软的绒毛。','刷理绒毛方向会影响布料反光。','纺织'),C('nap.s3','打盹','The cat napped in the sun while the family prepared lunch in the next room.','家人在隔壁准备午餐时，猫咪在阳光下打盹。','The cat napped in the sun / while the family prepared lunch / in the next room.','nap 作动词表示短时间睡觉或打盹。','猫在午间短睡。')],M('Luis took a nap for a week without waking, although the sentence meant a brief daytime sleep.','Luis took a short nap after work before driving home.','持续一周的睡眠不能称为通常意义上的短时 nap。'),[q('When did Luis nap?','after his night shift','during his whole work week','before his shift began yesterday','路易斯夜班后短睡。',1),q('What did the tailor brush?','the raised surface threads of the coat','the cat’s fur','a metal nail','nap 在纺织语境指织物绒面。',2),q('In “the cat napped in the sun,” nap is a?','verb meaning sleep briefly','noun meaning a fabric surface','verb meaning fasten with a nail','napped 表示短暂睡觉。',3,'grammar'),q('Which is a nap in the cloth sense?','the soft raised surface of velvet','a short sleep after lunch','a short story about a cat','布料表面的短绒是 nap。',2,'meaning')]);
P('nape','Nape means the back upper part of the neck; its origin is uncertain and may involve an Old French word for a cup, though that proposal is speculative.',C('nape.s1','颈后部位','The physiotherapist placed a warm compress on the nape of the patient’s neck to ease muscle tension.','理疗师把热敷袋放在病人颈后，帮助缓解肌肉紧张。','The physiotherapist placed a warm compress / on the nape of the patient’s neck / to ease / muscle tension.','nape 作名词特指颈部后上方。','热敷位置在脖子后面。','医疗'),M('The physiotherapist placed the compress on the nape, the front of the throat beneath the chin.','The physiotherapist placed the compress on the nape, at the back of the neck.','nape 是颈后而不是喉咙前侧。','confusable'),[q('Where did the therapist place the compress?','at the back of the patient’s neck','on the front of the throat','on the wrist','nape 指颈后上方。'),q('Why was the compress used?','to ease muscle tension','to measure a nanometer','to mend a torn napkin','热敷帮助缓解颈部肌肉紧张。'),q('Which body part is the nape?','the back of the neck','the palm of the hand','the front of the knee','nape 指后颈。',1,'meaning'),q('The word nape has what etymological status?','its exact origin is uncertain','it is certainly from Latin for “neck”','it comes from the name of a modern doctor','词源说法尚无定论。',1,'word-formation')]);
P('napkin','Napkin comes from nape (“tablecloth,” through Old French from Latin mappa) plus Middle English -kin, “little”; it first named a small cloth for meals.',[C('napkin.s1','餐桌用品','Each diner placed a paper napkin beside the plate before the soup was served.','汤上桌前，每位用餐者都在盘子旁放了一张纸餐巾。','Each diner placed a paper napkin / beside the plate / before the soup was served.','napkin 通常指用餐时擦手擦嘴、保护衣物的布或纸巾。','纸巾放在餐盘旁用于用餐。','餐饮'),C('napkin.s2','卫生用品','The older American text uses napkin for a menstrual pad, a regional historical sense that differs from the usual table-cloth meaning.','这篇较早的美国文本用 napkin 指月经垫，这是一个地区性的旧义，与通常的餐桌餐巾义不同。','The older American text uses napkin / for a menstrual pad / a regional historical sense / that differs from the usual table-cloth meaning.','在部分美国旧用法中，napkin 也可指女性经期使用的卫生垫。','语境明确指出是旧文中的地区性用法。','用法')],M('The diners used a napkin to keep their clothes clean, but the restaurant provided a menstrual pad at each place setting.','The diners used a table napkin beside each plate to keep their clothes clean.','餐桌用的餐巾与经期卫生用品是不同义项。','confusable'),[q('What did each diner put beside the plate?','a paper table napkin','a cloth nape','a thermometer','餐桌上使用纸餐巾。',1),q('What does the older American text mean by napkin?','a menstrual pad','a paper used only at dinner','a neck compress','该历史用法指经期卫生垫。',2,'context'),q('Which meaning is usual in a restaurant setting?','a cloth or paper used while eating','a pad for a medical scan','a fabric’s raised nap','餐厅语境通常指用餐餐巾。',1,'meaning'),q('What is the origin of the meal sense?','a diminutive of an old word for a tablecloth','a Greek word meaning sleep','a Scandinavian term for a complaint','napkin 来自 nape 加“小”的后缀。',1,'word-formation')]);
P('narcosis','Narcosis came from Modern Latin narcosis, from Greek narkōsis, “numbing,” from narkoun, “to benumb”; it is drug- or pressure-related drowsiness or insensibility.',C('narcosis.s1','麻醉性昏睡','The diver ascended slowly after nitrogen narcosis made his judgement unreliable at depth.','氮醉使潜水员在深处判断力下降后，他缓慢上浮。','The diver ascended slowly / after nitrogen narcosis / made his judgement unreliable / at depth.','narcosis 作名词指由药物或潜水深度压力造成的昏睡、迟钝或知觉减弱。','氮在深水压力下造成判断迟钝，需缓慢上浮。','潜水'),M('The diver experienced narcosis but remained fully alert, clear-headed, and unaffected by pressure or drugs.','The diver experienced narcosis as nitrogen pressure impaired his judgement underwater.','判断力完全不受影响与 narcosis 所指的迟钝状态相反。','meaning'),[q('What impaired the diver’s judgement?','nitrogen narcosis at depth','a low camera battery','a short nap on shore','深水中的氮醉影响判断。'),q('What did the diver do after it began?','ascended slowly','descended rapidly','mutinied against the boat','潜水员缓慢上浮。'),q('Narcosis is a state of?','drowsiness or reduced awareness','excellent alertness','muscle growth','narcosis 指昏睡或知觉减弱。',1,'meaning'),q('Which can cause narcosis during a dive?','nitrogen under pressure at depth','a paper napkin','a bright muted colour','深水压力下的氮可导致氮醉。',1,'context')]);
})();

(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('narcotic','Narcotic came through Old French and Medieval Latin from Greek narkōtikos, “making numb,” from narkoun (“benumb”).',C('narcotic.s1','药理学','The label warns that the narcotic may cause drowsiness, so patients should follow the prescriber’s directions and avoid driving if affected.','标签提醒这种麻醉性药物可能引起嗜睡，因此患者应遵从开药者的说明，并在受影响时避免驾驶。','The label warns / that the narcotic may cause drowsiness / so patients should follow the prescriber’s directions / and avoid driving if affected.','narcotic 作名词指能使人困倦、减轻痛觉的药物，也可用于某些非法毒品。','标签强调嗜睡风险和遵循处方说明。','医学'),M('The label calls the medicine a narcotic because it sharpens alertness and prevents any drowsiness.','The label calls the medicine a narcotic because it may cause drowsiness and reduce sensation.','使人清醒而不产生迟钝，与麻醉性药物的定义相反。','meaning'),[q('What effect does the label warn about?','drowsiness','stronger colour vision','improved navigation','narcotic 可能使人困倦。'),q('What should patients do?','follow the prescriber’s directions','ignore the label and drive if sleepy','share the medication with others','应按开药者说明使用。'),q('A narcotic is a substance that may?','induce sleepiness or blunt sensation','increase a person’s height','measure one billionth of a metre','该词指可能令人困倦或感觉迟钝的药物。',1,'meaning'),q('Which word is closest to the Greek source narkoun?','benumb','narrate','name','narkoun 有使麻木、失去知觉之意。',1,'word-formation')]);
P('narrate','Narrate is a back-formation from narration or from Latin narratus, related to narrare (“tell, explain”); it means to recount events or provide spoken commentary.',[C('narrate.s1','按序叙述','The witness narrated the events in order, beginning with the alarm and ending when firefighters arrived.','证人按顺序叙述经过，从警报响起讲到消防员到场。','The witness narrated the events in order / beginning with the alarm / and ending / when firefighters arrived.','narrate 作及物动词可接 events，表示按顺序讲述事件。','例句按发生次序交代事件。'),C('narrate.s2','影片解说','A wildlife presenter narrates the documentary, explaining how the migrating cranes find their winter wetlands.','一位野生动物节目主持人为纪录片配旁白，解释迁徙的鹤如何找到冬季湿地。','A wildlife presenter narrates the documentary / explaining how the migrating cranes / find their winter wetlands.','narrate 也可指为影片、节目或展览提供口头解说。','主持人的声音解释画面内容。','媒体')],M('The presenter narrated the documentary by remaining silent while no spoken explanation was provided.','The presenter narrated the documentary by speaking over the images to explain what was happening.','没有口头讲述或解释就不是作旁白。'),[q('In what order did the witness narrate the events?','from the alarm to the firefighters’ arrival','from the following morning backward to the alarm','without describing any event','证人按事件先后讲述。',1),q('What did the wildlife presenter narrate?','a documentary about migrating cranes','a silent paper map','a short nap','主持人为纪录片解说。',2),q('To narrate a film is to?','speak words explaining its events or images','edit its images into a montage','write its ticket price','narrate 可作影片旁白。',2,'meaning'),q('Which verb form is correct?','The witness narrated the incident.','The witness narrate the incident yesterday.','The witness was narration the incident.','过去叙述用 narrated。',1,'grammar')]);
P('narration','Narration comes from Latin narratio, “a telling or account,” from narrare (“relate, explain”); it names the act of telling events or the spoken words in a programme.',[C('narration.s1','叙述行为','Her narration of the rescue followed the timeline carefully, from the first radio call to the final evacuation.','她对救援经过的叙述严谨遵循时间线，从第一次无线电呼叫讲到最后撤离。','Her narration of the rescue followed the timeline / carefully / from the first radio call / to the final evacuation.','narration 作名词可指按顺序讲述事件的行为。','叙述覆盖救援事件的起止过程。'),C('narration.s2','影片旁白','The film’s narration describes each stage of the glacier survey while the camera shows the field team at work.','影片旁白在镜头展示野外团队工作的同时，介绍冰川勘测的每个阶段。','The film’s narration describes each stage / of the glacier survey / while the camera shows / the field team at work.','narration 也可指影片或节目的口头解说内容。','旁白为同步画面提供说明。','媒体')],M('The film’s narration was a series of spoken explanations, but the director said that the film had no narration.','The film’s narration supplied spoken explanations of the survey as the images appeared.','有口头解释内容就不能说完全没有 narration。','meaning'),[q('What did her rescue narration follow?','the timeline of events','the film’s colour palette','the national border','叙述从首次呼叫到撤离按序展开。',1),q('What accompanies the glacier survey footage?','spoken explanations of each stage','a silent map with no words','a weather warning only','旁白介绍勘测各阶段。',2),q('Narration can mean?','the act of telling events or the spoken words themselves','the person who listens to a story','the setting where a film is shown','narration 可指讲述行为或旁白内容。',1,'meaning'),q('Which phrase refers to commentary heard in a film?','the film’s narration','the film’s nationality','the film’s nape','film narration 是影片旁白。',2,'context')]);
P('narrative','Narrative is from Latin narrativus, “suited to telling,” related to narrare (“tell”); it means a story or an account of connected events.',C('narrative.s1','事件叙事','The report offers a narrative of the flood, linking the first rainfall warnings to the town’s recovery months later.','报告叙述了洪水经过，把最初的降雨警报与数月后城镇的恢复联系起来。','The report offers a narrative of the flood / linking the first rainfall warnings / to the town’s recovery / months later.','narrative 作名词指一段故事或一系列相关事件的叙述。','报告把洪水与后续恢复组织成完整叙事。','写作'),M('The report called its narrative a connected account of the flood, but it contained no events or description at all.','The report’s narrative connected the first flood warnings with the town’s later recovery.','没有事件内容或描述，就不构成事件叙事。'),[q('What does the report’s narrative describe?','the flood and the town’s recovery','a recipe for a narcotic','the history of a naval uniform','报告把洪水与恢复联系起来。'),q('A narrative is?','a story or account of connected events','a single unexplained measurement','a person who reads silently','narrative 指故事或事件叙述。'),q('Which text is a narrative?','an account linking a storm warning to its aftermath','a list of unrelated numbers with no explanation','a blank sheet','叙述把相关事件串联起来。',1,'context'),q('Narrative is related to the verb?','narrate','narrow','nauseate','narrative 与讲述动词 narrate 同源。',1,'word-formation')]);
P('narrator','Narrator comes from Latin narrator, an agent noun from narrare (“tell”); it names a person or voice that tells a story or explains a film.',C('narrator.s1','讲述者','The narrator speaks in the first person, so readers learn the events through her memories and limited point of view.','叙述者以第一人称发言，因此读者通过她的回忆和有限视角了解事件。','The narrator speaks in the first person / so readers learn the events / through her memories / and limited point of view.','narrator 作名词指讲述故事的人或影片解说的声音。','第一人称视角来自叙述者的记忆。','文学'),M('The novel’s narrator tells the story, but the book contains no voice or person presenting any events.','The novel’s narrator presents the story through a particular point of view.','讲述故事的人或声音就是 narrator。'),[q('From whose viewpoint do readers learn the events?','the first-person narrator’s','the reader’s neighbour’s','the film editor’s only','第一人称叙述由 narrator 提供视角。'),q('What does a narrator do?','tells a story or explains a film','measures a nanometer','fits a mute to a trumpet','narrator 是讲述者或旁白。'),q('Who is the narrator in an audio documentary?','the voice that tells or explains the story','the person who repairs the recorder','the audience member who buys a ticket','解说故事的声音是 narrator。',1,'meaning'),q('A first-person narrator often uses?','I and my','you and your only','they and their only','第一人称叙述常使用 I、my。',1,'grammar')]);
P('narrow','Narrow comes from Old English nearu, “confined or cramped”; as an adjective it describes little width or restricted scope, and as a verb it can become or make something narrower.',[C('narrow.s1','宽度有限','The narrow footbridge allows only one person to cross at a time, so hikers waited on the bank.','这座狭窄的人行桥一次只容一人通过，因此徒步者在岸边等候。','The narrow footbridge allows only one person to cross / at a time / so hikers waited / on the bank.','narrow 作形容词表示从一侧到另一侧距离较小。','桥面宽度有限，需要单人通行。'),C('narrow.s2','范围有限','The committee’s narrow review considered only safety costs and left environmental effects for a later report.','委员会这次范围有限的审查只考虑了安全成本，把环境影响留待后续报告。','The committee’s narrow review considered only safety costs / and left environmental effects / for a later report.','narrow 也可表示范围或视野受到限制，亦可形容险胜。','审查只涉及安全成本，并非全面评估。','评估'),C('narrow.s3','缩小范围','The search narrowed to three farms after the investigators compared delivery records and weather reports.','调查人员比对配送记录和天气报告后，搜索范围缩小到三个农场。','The search narrowed to three farms / after the investigators compared / delivery records and weather reports.','narrow 作动词可表示范围变小，常用 narrow to + 范围。','候选地点由更多缩至三个。'),C('narrow.s4','狭窄水道','The ferry passed through a narrow between the island and the mainland as the tide began to turn.','潮水开始转向时，渡船穿过了岛屿与大陆之间的一段狭窄水道。','The ferry passed through a narrow / between the island and the mainland / as the tide began to turn.','narrow 作名词可指道路、河流或海面中的狭窄部分或海峡。','渡船从两岸之间的窄水道经过。','地理')],M('The search narrowed to three farms after the team added hundreds of new possible locations.','The search narrowed to three farms after the team ruled out the other locations.','新增大量地点会扩大而不是缩小搜索范围。','meaning'),[q('How many people can cross the footbridge at once?','one','three','hundreds','桥面狭窄，一次只容一人。',1),q('What did the committee leave for a later report?','environmental effects','safety costs','the bridge’s width','这次审查只看安全成本。',2),q('What happened to the search area?','it became limited to three farms','it expanded to hundreds of farms','it stopped using delivery records','动词 narrow 表示搜索范围变小。',3,'grammar'),q('What did the ferry pass through?','a narrow stretch of water between land masses','a wide open ocean with no shores','a mountain summit','narrow 作名词可指狭窄海峡或水道。',4,'meaning')]);
P('narrowly','Narrowly is narrow plus -ly; it means only just, with a small margin, or in a restricted and focused way.',C('narrowly.s1','险些发生','The cyclist narrowly avoided the fallen branch by swerving onto the empty shoulder at the last second.','骑车人最后一刻急转到空旷路肩，险些撞上倒下的树枝。','The cyclist narrowly avoided the fallen branch / by swerving / onto the empty shoulder / at the last second.','narrowly 可修饰动词表示勉强、险些或以很小差距完成。','只差一点撞上，属于 narrowly avoided。'),M('The cyclist narrowly avoided the branch by hitting it squarely at full speed.','The cyclist narrowly avoided the branch by swerving past it at the last second.','正面撞上树枝不能称为成功避开。'),[q('What did the cyclist avoid?','a fallen branch','a paper napkin','a ferry crossing','骑车人避开了倒树枝。'),q('How did the cyclist avoid it?','by swerving at the last second','by stopping a week earlier','by moving the branch with a crane','他最后一刻急转，险些撞上。'),q('“The team narrowly won” means it?','won by a small margin','won by a huge amount','did not compete','narrowly 可指以微弱优势获胜。',1,'meaning'),q('Which event was narrowly avoided?','a car almost struck a barrier but missed it','a driver stopped far from any obstacle','a team won by a record margin','narrowly avoided 表示险些发生但未发生。',1,'context')]);
P('nascent','Nascent comes from Latin nascentem, “being born,” from nasci (“be born”); it describes something just beginning to exist or develop.',C('nascent.s1','萌芽阶段','The nascent community garden had only six plots, but nearby residents were already organising a seed exchange.','这个刚刚起步的社区花园只有六块地，但附近居民已开始组织种子交换。','The nascent community garden had only six plots / but nearby residents / were already organising / a seed exchange.','nascent 作形容词描述才刚出现或开始发展的事物。','花园规模尚小，但项目已在发展。','社区'),M('The nascent project had operated unchanged for a century before anyone began it.','The nascent project had only just begun and was still taking shape.','已经持续一个世纪的成熟项目并非刚刚起步。','meaning'),[q('How many plots did the nascent garden have?','six','sixty thousand','none because it was closed','花园初期只有六块地。'),q('What were residents organising?','a seed exchange','a national election','a film narration','社区成员开始组织种子交换。'),q('A nascent business is?','newly beginning to develop','long established and unchanged','about to close after centuries','nascent 表示处于初创阶段。',1,'meaning'),q('Which effort is nascent?','a new neighbourhood group holding its first meeting','a mature organisation with a hundred-year history','a finished project no longer operating','刚成立、初次开会的团体属于 nascent。',1,'context')]);
P('nastiness','Nastiness is nasty plus -ness; it can mean mean behaviour or something filthy and unpleasant.',[C('nastiness.s1','刻薄行为','The email’s nastiness surprised the team because it mocked a colleague’s accent instead of addressing the design issue.','这封邮件的刻薄让团队吃惊，因为它嘲笑同事的口音，而没有讨论设计问题。','The email’s nastiness surprised the team / because it mocked a colleague’s accent / instead of addressing / the design issue.','nastiness 作不可数名词可指刻薄、恶意的行为。','嘲笑同事而不谈工作问题体现恶意。'),C('nastiness.s1','肮脏难闻','The cleaner found the nastiness beneath the sink, where spoiled food had leaked from a torn bag.','清洁工在水槽下发现了污秽脏东西，变质食物从破袋中漏了出来。','The cleaner found the nastiness beneath the sink / where spoiled food / had leaked / from a torn bag.','nastiness 也可指污秽、令人不快的东西。','漏出的变质食物造成脏污。','清洁')],M('The email showed no nastiness because it respectfully addressed the design issue without insulting anyone.','The email showed nastiness by ridiculing a colleague rather than discussing the work.','尊重地讨论问题而不侮辱他人，不是刻薄行为。','meaning'),[q('What made the email nasty?','it mocked a colleague’s accent','it proposed a design revision','it thanked the whole team','嘲笑同事体现刻薄。',1),q('Where did the cleaner find the filthy mess?','beneath the sink','inside the committee’s report','on the footbridge','破袋漏出的食物弄脏了水槽下方。',1),q('Nastiness can refer to?','mean behaviour or filthy unpleasantness','a newly beginning project','a national government','该名词有刻薄和污秽两类相关用法。',1,'meaning'),q('Which is an example of nastiness?','mocking a co-worker instead of discussing their proposal','offering constructive feedback politely','cleaning a spill promptly','嘲笑他人而不谈事属于恶意行为。',1,'context')]);
P('nasty','Nasty has uncertain origins; it was recorded in Middle English for something filthy and later broadened to unpleasant, mean, or dangerous things.',[C('nasty.s1','令人不快','A nasty smell came from the forgotten lunch container, so Mei sealed it in a bag before cleaning it.','被遗忘的午餐盒散发出难闻气味，梅先把它封进袋子里再清理。','A nasty smell came from the forgotten lunch container / so Mei sealed it in a bag / before cleaning it.','nasty 可表示气味、经历或事物令人非常不快。','午餐盒散发难闻气味。','日常'),C('nasty.s2','刻薄言行','He made a nasty remark about the new trainee’s accent, and the supervisor asked him to apologise.','他对新实习生的口音说了刻薄的话，主管要求他道歉。','He made a nasty remark / about the new trainee’s accent / and the supervisor / asked him to apologise.','nasty 也可形容不友善、恶意或冒犯的言行。','主管要求为刻薄言论道歉。','人际'),C('nasty.s3','严重危险','The skier suffered a nasty cut on his arm after catching it on a sharp edge of the broken sign.','滑雪者的手臂被破损标牌的锋利边缘划伤，伤口很严重。','The skier suffered a nasty cut on his arm / after catching it / on a sharp edge / of the broken sign.','nasty 还可形容伤势或问题严重、凶险。','伤口由尖锐边缘造成，程度较重。','医疗')],M('The skier had a nasty cut, but the wound was tiny, harmless, and required no attention.','The skier had a nasty cut that needed prompt cleaning and medical attention.','轻微无害的划痕不能称作严重伤口。','meaning'),[q('What smelled nasty?','the forgotten lunch container','a clean flower bouquet','the new trainee’s badge','变质午餐盒散发难闻气味。',1),q('Why was the remark nasty?','it insulted the trainee’s accent','it welcomed the trainee kindly','it described the weather','刻薄言论针对实习生口音。',2),q('What does nasty describe in “a nasty cut”?','a severe or dangerous injury','a pleasantly scented meal','a low speaking voice','此处 nasty 表示伤势严重。',3,'meaning'),q('Which situation is nasty in the unpleasant sense?','a foul smell from spoiled food','a fresh clean room','a polite greeting','令人作呕的气味体现此义。',1,'context')]);
P('natal','Natal comes from Latin natalis, “of birth,” from nasci (“be born”); it relates to the time or place of someone’s birth.',C('natal.s1','出生地点','The author returned to her natal town for the first time in decades to open a library in the house where she grew up.','这位作家几十年来首次回到出生并成长的小镇，在儿时住过的房子里开办图书馆。','The author returned to her natal town / for the first time in decades / to open a library / in the house where she grew up.','natal 作形容词表示与出生时间或出生地点相关。','她回到 natal town，即出生地。','传记'),M('The author called a city she had never visited her natal town, although she was born and raised elsewhere.','The author called the town where she was born her natal town.','从未出生或生活过的地方不是某人的出生地。'),[q('Where did the author return?','the town where she was born and grew up','a city she had never visited','the capital where the library was approved','她回到自己的出生并成长之地。'),q('What does natal mean?','connected with a person’s birth','connected with a person’s retirement','connected with the whole nation','natal 与出生相关。'),q('Which document contains natal information?','a record of a child’s birth place and date','a ship’s navigation chart','a list of national election results','出生记录包含 natal 信息。',1,'context'),q('Natal comes from Latin natalis, related to?','birth','sleep','colour','natalis 指与出生有关。',1,'word-formation')]);
P('nation','Nation comes through Old French nacion from Latin natio (“birth, people”); it can mean a country with its own government or its people considered together.',[C('nation.s1','国家政体','The nation adopted a new constitution that defined the powers of parliament and the courts.','这个国家通过了新宪法，明确规定议会和法院的权力。','The nation adopted a new constitution / that defined the powers / of parliament / and the courts.','nation 作名词可指拥有自身土地和政府的大型政治共同体。','宪法、议会和法院体现国家政体。','政治'),C('nation.s2','全体国民','The nation observed a minute of silence, with people across the country joining the memorial from their homes and workplaces.','全国民众在家中和工作场所共同默哀一分钟。','The nation observed a minute of silence / with people across the country joining / the memorial / from their homes and workplaces.','nation 也可指作为整体看待的一个国家的人民。','全国各地的民众共同参与纪念。','社会')],M('The nation adopted a constitution, but the sentence says it had no people, land, or government.','The nation adopted a constitution for its people and governing institutions.','拥有宪法和政府机构的政治共同体与“没有人民、土地或政府”矛盾。'),[q('What did the nation adopt?','a new constitution','a new napkin design','a narcotic label','例句说国家通过新宪法。',1),q('Who joined the minute of silence?','people throughout the country','only the parliament building','the courts alone','nation 在此指全国人民。',2),q('Nation can refer to?','a country with government or its people as a group','a single city street only','one person’s birth record','nation 可指国家或国民整体。',1,'meaning'),q('Which phrase uses nation to mean people?','The entire nation mourned together.','The nation signed a treaty with its neighbour.','The nation has a parliament building.','mourned together 指全体国民。',2,'context')]);
P('national','National is nation plus -al and means relating to or belonging to a whole country or its people.',C('national.s1','全国赛事','The national debate competition brought school teams from every region to the capital for the final round.','全国辩论赛把来自各地区的学校队伍带到首都参加决赛。','The national debate competition brought school teams / from every region / to the capital / for the final round.','national 作形容词修饰覆盖整个国家或全国人民的事物。','参赛队来自全国各地区。','教育'),M('The organisers called a competition national even though it included one neighbourhood school and no other region.','The organisers called it national because school teams came from every region.','只有一个社区学校参赛不具备全国范围。'),[q('Where did the teams come from?','every region of the country','one neighbourhood only','several foreign continents','来自各地区体现全国赛事。'),q('Where was the final round held?','in the capital','in a single classroom abroad','on a ship at sea','例句说决赛在首都举行。'),q('A national holiday is?','observed across a country','celebrated by one family only','a person’s birth date','national 表示国家或全国范围相关。',1,'meaning'),q('National is formed from nation plus?','-al','-ish','-ize','-al 可把 nation 派生为形容词 national。',1,'word-formation')]);
P('nationalism','Nationalism is national plus -ism; it is identification with one’s nation, sometimes including support for independence or claims of national superiority.',C('nationalism.s1','政治理念','The historian distinguishes civic nationalism, based on shared citizenship, from movements that claim one nation is superior to others.','历史学家区分以共同公民身份为基础的公民民族主义，以及宣称本民族优越于其他民族的运动。','The historian distinguishes civic nationalism / based on shared citizenship / from movements / that claim one nation is superior to others.','nationalism 作名词指对本民族的认同，也可能包含争取独立或强调优越性的政治主张。','例句显示民族主义内部也有不同形式。','政治'),M('The historian defined nationalism as a political belief that rejects any identification with one’s nation.','The historian defined nationalism as identification with one’s nation, which can take different political forms.','否认对本民族认同与 nationalism 的核心定义相反。','meaning'),[q('What does civic nationalism in the example rest on?','shared citizenship','a claim of superiority only','a shared weather forecast','历史学家指出公民民族主义以共同公民身份为基础。'),q('What claim does the other movement make?','one nation is superior to others','no nation has any identity','all countries share one government','另一运动宣称本民族优越。'),q('Nationalism can include?','identification with a nation or a demand for independence','a study of fungi','a narrow water passage','nationalism 与民族认同或独立诉求有关。',1,'meaning'),q('Which statement is accurate?','nationalism can appear in different political forms','all nationalism has exactly the same goals','nationalism is a type of government official','民族主义可有不同政治形式。',1,'context')]);
P('nationalist','Nationalist is national plus -ist; it names someone who strongly supports the interests or independence of their nation.',C('nationalist.s1','政治身份','The nationalist argued for greater local self-government, while also explaining how minority rights would be protected.','这位民族主义者主张扩大地方自治，同时解释如何保护少数群体的权利。','The nationalist argued for greater local self-government / while also explaining / how minority rights / would be protected.','nationalist 作名词指强烈支持本民族利益或独立诉求的人。','地方自治主张体现其政治立场。','政治'),M('The speaker was called a nationalist even though she argued that her nation should have no self-government or distinct interests.','The speaker was called a nationalist because she supported greater self-government for her nation.','反对本民族自治和利益的主张不符合该语境中的 nationalist。','meaning'),[q('What did the nationalist support?','greater local self-government','ending all local representation','a new national napkin','她主张扩大地方自治。'),q('What issue did she also address?','protecting minority rights','raising the river’s temperature','renaming the research vessel','她解释了如何保护少数群体权利。'),q('A nationalist is someone who?','strongly supports their nation’s interests or independence','opposes any national identity','studies national biology','nationalist 指支持本民族利益或独立的人。',1,'meaning'),q('Which person might be described as a nationalist?','an organiser campaigning for national self-rule','a scientist measuring cell size','a narrator describing a film','争取本民族自治的人可能称为 nationalist。',1,'context')]);
P('nationalistic','Nationalistic is national plus -istic and describes intense loyalty to one’s nation, sometimes at the expense of other countries.',C('nationalistic.s1','强烈民族倾向','The editorial warned that nationalistic slogans portraying neighbouring countries as inferior could inflame tensions.','社论警告，把邻国描绘得低人一等的民族主义口号可能激化紧张关系。','The editorial warned / that nationalistic slogans portraying neighbouring countries as inferior / could inflame / tensions.','nationalistic 作形容词描述强烈的民族忠诚，有时带排外或贬低他国的意味。','把邻国说成低人一等体现排外民族主义。','政治'),M('The editorial called the slogan nationalistic, although it expressed equal respect for every country and no national preference.','The editorial called the slogan nationalistic because it praised one nation by belittling its neighbours.','平等尊重各国、不偏向任何民族与此处排外的 nationalistic 不符。','meaning'),[q('What could inflame tensions?','slogans portraying neighbours as inferior','a neutral weather notice','a national debate about school uniforms','贬低邻国的口号可能激化紧张。'),q('Nationalistic can suggest?','intense national loyalty, sometimes at others’ expense','complete indifference to every country','a focus on birth records','该词可带有排外或贬低他国的含义。'),q('Which message is nationalistic in the critical sense?','our country is superior and neighbouring peoples are inferior','every country deserves equal respect','citizens should compare policy evidence','贬低其他国家体现此处 nationalistic 倾向。',1,'context'),q('Nationalistic is a/an?','adjective describing a kind of national loyalty','noun for a birth certificate','verb meaning name someone','nationalistic 是形容词。',1,'grammar')]);
P('nationality','Nationality is national plus -ity; it can mean legal belonging to a country or, in some contexts, a cultural or ethnic group.',[C('nationality.s1','法律国籍','The application asks for the child’s nationality, meaning the country to which the child legally belongs.','申请表询问孩子的国籍，即孩子在法律上归属的国家。','The application asks for the child’s nationality / meaning the country / to which the child / legally belongs.','nationality 常指一个人依法归属的国家或公民身份。','问题针对法律上的国家归属。','法律'),C('nationality.s2','文化群体','The museum grouped the woven patterns by nationality of origin, comparing designs from several distinct cultural communities.','博物馆按文化群体来源整理编织图案，并比较几个不同社群的设计。','The museum grouped the woven patterns / by nationality of origin / comparing designs / from several distinct cultural communities.','nationality 也可指具有共同文化和历史的群体，需结合上下文判断。','此处说的是不同文化群体的传统图案。','文化')],M('The form asked for a child’s nationality, and the clerk filled in the child’s favourite colour.','The form asked for a child’s nationality, and the clerk recorded the country of legal belonging.','国籍栏目要求国家归属，不是个人喜好。','word-choice'),[q('What does the application ask for?','the child’s legal country of belonging','the child’s favourite colour','the child’s school subject','表格询问法律国籍。',1),q('What did the museum compare?','patterns from distinct cultural communities','legal birth records only','national debate teams','此处 nationality 指文化群体来源。',2),q('In a passport form, nationality normally means?','legal belonging to a country','a person’s preferred language only','the design of a national flag','法律表格中的 nationality 通常指国籍。',1,'meaning'),q('In a museum study, nationality may refer to?','a cultural group with shared history','only a passport number','one individual’s family nickname','语境中可指文化和历史相近的群体。',2,'context')]);
P('nationally','Nationally is national plus -ly and means across or in a way that affects the whole country.',C('nationally.s1','全国范围','The survey was conducted nationally, with households sampled in cities, rural districts, and remote islands.','这项调查在全国范围内开展，样本涵盖城市、农村地区和偏远岛屿的家庭。','The survey was conducted nationally / with households sampled / in cities, rural districts, / and remote islands.','nationally 作副词修饰 conducted，表示覆盖全国范围。','样本覆盖多种地区，而非单一城市。','调查'),M('The survey was conducted nationally, but every participant came from one street in a single town.','The survey was conducted nationally, with participants sampled across the country.','只调查一条街不能称为全国范围开展。'),[q('Where were households sampled?','in cities, rural districts, and remote islands','on one street only','in one office building','样本来自全国多种地区。'),q('What does nationally mean here?','across the whole country','within one neighbourhood','outside the country only','nationally 表示在全国范围。'),q('Which survey was conducted nationally?','one sampling respondents in all major regions','one interviewing a single family','one measuring a single school’s hallway','全国多地区抽样属于 nationally。',1,'context'),q('Nationally is a/an?','adverb modifying how broadly something is done','noun for a country’s citizen','adjective describing a passport','nationally 是副词。',1,'grammar')]);
P('nationwide','Nationwide combines nation and wide; it can describe something covering all parts of a country or say that it occurs throughout the country.',[C('nationwide.s1','全国措施','A nationwide vaccination programme began in spring, with clinics opening in every province and territory.','一项全国疫苗接种计划于春季启动，各省区都开设了接种点。','A nationwide vaccination programme began in spring / with clinics opening / in every province / and territory.','nationwide 作形容词修饰覆盖全国的计划、活动或措施。','接种点分布于各省区。','公共卫生'),C('nationwide.s2','各地发生','The alert was broadcast nationwide within minutes, reaching radio stations in both coastal and inland regions.','这条警报几分钟内便在全国各地播出，沿海和内陆地区的电台都收到了。','The alert was broadcast nationwide within minutes / reaching radio stations / in both coastal / and inland regions.','nationwide 也可作副词，表示遍及全国地发生或传播。','警报在全国不同地区传播。','媒体')],M('The government described a programme as nationwide even though it operated in one city and excluded every other region.','The government described a programme as nationwide because it operated in every province and territory.','只在一个城市实施不属于全国覆盖。'),[q('Where did the vaccination clinics open?','in every province and territory','in one city only','in coastal regions abroad','接种点覆盖省区。',1),q('How quickly did the alert travel?','it was broadcast across the country within minutes','it remained in one building for weeks','it was sent only to one coast','警报迅速传至全国各地。',2),q('Which phrase uses nationwide as an adjective?','a nationwide programme','the programme spread nationwide','the nation nationalised the programme','修饰 programme 的 nationwide 是形容词。',1,'grammar'),q('Which sentence uses nationwide as an adverb?','The warning was heard nationwide.','A nationwide warning was issued.','The warning’s nation was wide.','修饰 was heard 的 nationwide 是副词。',2,'grammar')]);
P('native','Native came through Old French natif from Latin nativus, “innate or born,” from nasci (“be born”); it can describe one’s birthplace, a species naturally from a place, or a person born there.',[C('native.s1','出生地相关','After living abroad for years, Omar returned to his native city and recognised the old harbour road immediately.','奥马尔在国外生活多年后回到自己的出生城市，立刻认出了旧港口公路。','After living abroad for years / Omar returned to his native city / and recognised / the old harbour road immediately.','native 作形容词可描述某人出生或成长的地方。','native city 指奥马尔出生或成长之城。'),C('native.s2','本地物种','The conservation team planted native grasses along the riverbank because they thrive in the local soil and support local insects.','保护团队在河岸种植本地原生草类，因为它们适应当地土壤，也能支持本地昆虫。','The conservation team planted native grasses / along the riverbank / because they thrive in local soil / and support local insects.','native 形容物种时指自然生长或生活于某地、并非从外地引入。','草类适应本地环境并支持当地生态。','生态'),C('native.s3','本地出生者','As a native of the island, Lena knows which footpaths remain open after heavy rain.','莱娜是这座岛的本地出生者，因此知道暴雨后哪些小路仍然开放。','As a native of the island / Lena knows / which footpaths remain open / after heavy rain.','native 可作可数名词，指在某地出生的人，常用 native of + 地点。','native of the island 表示出生于岛上的人。')],M('The conservation team called the imported grass native to the island even though it had been brought from another continent last year.','The conservation team called the grass native to the island because it grows there naturally.','近期从外地引进的物种并非当地原生种。','meaning'),[q('Where did Omar return?','the city where he was born or grew up','a city he had never visited','the capital of a different country','native city 指他的出生或成长地点。',1),q('Why plant native grasses?','they thrive in local soil and support local insects','they were recently imported from another continent','they cannot grow near rivers','本地原生草适应当地土壤并支持昆虫。',2),q('What does “a native of the island” mean?','a person born there','a visitor staying there for one week','a grass species from another continent','native of 指出生于该地的人。',3,'meaning'),q('Which plant is native to a region?','one that grows there naturally without being introduced','one planted there yesterday after import','one that cannot survive in its local soil','native 物种自然生长于当地。',2,'context')]);
})();

(function(){
'use strict';
const D=globalThis.RA.D;
const q=(prompt,answer,d1,d2,explain,sense=1,type='meaning')=>({prompt,answer,d1,d2,explain,sense,type});
const C=(senseId,domain,en,zh,structure,grammar,rationale)=>({senseId,domain,en,zh,structure,grammar,rationale,sourceType:'authored'});
const M=(wrong,right,reason,errorType='meaning')=>({errorType,wrong,right,reason});
const E=(origin,w)=>({origin,prefix:null,root:null,suffix:null,source:'Etymonline: https://www.etymonline.com/word/'+w.toLowerCase().replaceAll(' ','-')});
const P=(w,origin,c,m,qs)=>D(w,{etymology:E(origin,w),contexts:Array.isArray(c)?c:[c],mistakes:[m],quiz:qs.map((x,i)=>({id:w+'.q'+(i+1),senseId:w+'.s'+x.sense,type:'辨义与用法',prompt:x.prompt,options:[x.answer,x.d1,x.d2],answer:x.answer,explain:x.explain,errorType:x.type}))});
P('native land','Native land combines native, from Latin nativus (“born”), with land; it means the country where someone was born.',C('native land.s1','故乡','After thirty years abroad, the musician returned to her native land and performed the songs she had learned as a child.','这位音乐家在国外生活三十年后回到祖国，演唱起童年学会的歌曲。','After thirty years abroad / the musician returned to her native land / and performed the songs / she had learned as a child.','native land 作名词短语指某人出生的国家或故乡。','返回出生国并演唱童年歌曲呼应故乡主题。'),M('The musician called a country where she had never been born her native land.','The musician called the country where she was born her native land.','native land 指出生的国家，不是从未出生过的地方。'),[q('Where did the musician return after living abroad?','the country where she was born','a country she had never visited','a ship’s home port only','native land 指她出生的国家。'),q('What did she perform there?','songs learned in childhood','a new film narration','a naval map','她回故乡演唱童年学会的歌曲。'),q('Native land is closest to?','one’s homeland or country of birth','a place visited for one holiday','a ship’s navigational device','该短语指故乡或出生国。',1,'meaning'),q('Which phrase refers to a person’s country of birth?','her native land','her naval fleet','her naturalistic style','native land 与出生地相连。',1,'context')]);
P('natty','Natty was recorded in the 18th century for “neat or smart,” perhaps altered from an older form related to neat.',C('natty.s1','整洁穿着','For the award dinner, Ken wore a natty jacket with clean lines and polished shoes.','参加颁奖晚宴时，肯穿了一件剪裁利落的时髦夹克和擦亮的鞋子。','For the award dinner / Ken wore a natty jacket / with clean lines / and polished shoes.','natty 作形容词描述衣着整洁、时髦利落。','衣服剪裁整洁，鞋子擦亮。','服饰'),M('Ken looked natty at the dinner in a stained jacket with loose seams and muddy shoes.','Ken looked natty at the dinner in a neat jacket and polished shoes.','脏污、破损的穿着不符合整洁时髦的 natty。','meaning'),[q('What did Ken wear?','a neat jacket and polished shoes','a muddy uniform and torn boots','a nautical life vest','整洁夹克与擦亮鞋子体现 natty。'),q('Where was Ken going?','an award dinner','a flooded riverbank','a costume workshop','他为晚宴穿着整洁时髦。'),q('Which outfit looks natty?','a tidy, stylish suit with clean shoes','a stained shirt with loose seams','a wet diving suit left unwashed','natty 指整洁、时髦利落。',1,'meaning'),q('Natty most naturally describes?','someone’s trim and fashionable clothes','a nation’s constitution','a feeling of nausea','该词常用来形容整洁时尚的着装。',1,'context')]);
P('natural','Natural came from Old French naturel and Latin naturalis, “by birth or according to nature,” from natura (“nature”).',C('natural.s1','天然材料','The builder chose natural stone for the garden wall rather than concrete blocks manufactured in a factory.','建筑工为花园围墙选择了天然石材，而不是工厂生产的混凝土砌块。','The builder chose natural stone / for the garden wall / rather than concrete blocks / manufactured in a factory.','natural 作形容词可指在自然界存在、未经人工制造的事物。','石材自然形成，与工厂制造的混凝土相对。'),M('The builder described factory-made concrete blocks as natural stone.','The builder used stone formed in nature rather than manufactured concrete blocks.','工厂制造的混凝土不是天然石材。','confusable'),[q('What material did the builder choose?','stone formed in nature','factory-made concrete blocks','a paper napkin','天然石材用于花园围墙。'),q('What did the builder choose it instead of?','manufactured concrete blocks','a native plant','a stone already in the wall','天然材料与工厂制造材料形成对照。'),q('Which object is natural in this sense?','an uncut rock from a riverbank','a plastic tile moulded in a factory','a painted metal sign','natural 指自然存在而非人工制造。',1,'meaning'),q('Natural is related historically to Latin natura, meaning?','nature or birth','navigation','sleep','natural 来自与自然、出生相关的词。',1,'word-formation')]);
P('naturalism','Naturalism is natural plus -ism; it names an artistic or literary approach depicting life without idealisation and a philosophy relying on natural causes.',[C('naturalism.s1','文学艺术','The novelist’s naturalism appears in plain descriptions of factory work, poverty, and the pressures that shape daily choices.','这位小说家的自然主义体现在对工厂劳动、贫困以及影响日常选择的压力所作的朴素描写中。','The novelist’s naturalism appears / in plain descriptions of factory work and poverty / and the pressures / that shape daily choices.','naturalism 在文艺中强调细致、不加理想化地描绘生活。','作品呈现社会环境如何影响人物，而不美化现实。','文学'),C('naturalism.s1','哲学观点','In philosophy, naturalism explains events through natural causes rather than supernatural intervention.','在哲学中，自然主义以自然原因解释事件，而不诉诸超自然干预。','In philosophy / naturalism explains events through natural causes / rather than supernatural intervention.','naturalism 也可指认为自然力量足以解释世界的哲学观点。','此处与超自然解释相对。','哲学')],M('The review called the novel naturalistic even though it idealised every character and concealed all hardship.','The review called the novel naturalistic because it portrayed hardship without idealising it.','美化所有人物并隐藏困难与自然主义写实手法相反。','meaning'),[q('What does the novelist describe plainly?','factory work, poverty, and daily pressures','only mythical heroes','a ship’s route','作品描绘现实生活及其压力。',1),q('What does philosophical naturalism rely on?','natural causes','supernatural intervention only','a single narrator’s opinion','自然主义哲学侧重自然原因。',1),q('In art and literature, naturalism aims to?','depict life in detail without idealising it','replace real life with perfect heroes','avoid describing social conditions','naturalism 文艺手法不美化生活。',1,'meaning'),q('Which work shows literary naturalism?','a novel showing how poverty and work shape people’s choices','a fairy tale in which every problem disappears magically','a travel brochure with no characters','现实环境及其影响被细致呈现。',1,'context')]);
P('naturalist','Naturalist is natural plus -ist; it names someone who observes wildlife and natural history, often outdoors.',C('naturalist.s1','野外观察者','The naturalist spent dawn beside the marsh, recording bird calls and noting which plants grew near the water.','博物学家黎明时在沼泽旁记录鸟鸣，并记下水边生长的植物。','The naturalist spent dawn beside the marsh / recording bird calls / and noting which plants / grew near the water.','naturalist 作名词指观察野生动物和自然史的人。','记录鸟类和植物属于博物学观察。','生态'),M('The naturalist studied wildlife by refusing to observe any animal, plant, or natural habitat.','The naturalist studied wildlife by observing birds and plants in their habitat.','不观察任何生物或栖息地，不符合 naturalist 的工作。'),[q('Where did the naturalist work at dawn?','beside a marsh','inside a naval shipyard','at a film studio','博物学家在沼泽旁观察自然。'),q('What did the naturalist record?','bird calls and nearby plants','a narration script','the crew’s nationality','他记录鸟鸣和植物。'),q('A naturalist is someone who studies?','wildlife and natural history','only national constitutions','nausea and medicine only','naturalist 指观察自然的人。',1,'meaning'),q('Which person is a naturalist?','a field observer cataloguing insects and plants','a navigator planning an aircraft route','a narrator describing a film','野外记录动植物的人是 naturalist。',1,'context')]);
P('naturalistic','Naturalistic is natural plus -istic; it can describe art following naturalism or something that looks convincingly like real life.',[C('naturalistic.s1','文艺风格','The play takes a naturalistic approach, with ordinary kitchen dialogue and conflicts shaped by work and rent.','这部戏采用自然主义风格，用日常厨房对话呈现由工作和房租带来的冲突。','The play takes a naturalistic approach / with ordinary kitchen dialogue / and conflicts shaped / by work and rent.','naturalistic 描述文艺手法时指不理想化、贴近生活现实。','对话与冲突来自平常生活。','戏剧'),C('naturalistic.s2','逼真效果','The sculptor gave the clay fox naturalistic fur and facial details so viewers initially mistook it for a real animal.','雕塑家为陶土狐狸塑出逼真的毛发和面部细节，让观众起初误以为它是真动物。','The sculptor gave the clay fox naturalistic fur and facial details / so viewers initially mistook it / for a real animal.','naturalistic 也可表示外观逼真、像自然实物。','细节逼真使雕像看起来像真狐狸。','艺术')],M('The clay fox looked naturalistic because it had no realistic features and was clearly a flat geometric shape.','The clay fox looked naturalistic because its fur and facial details resembled a real animal.','缺乏真实细节、明显为几何平面，不是逼真写实。'),[q('What shapes the play’s conflicts?','work and rent','a myth about a dragon','a ship’s tide chart','普通生活中的工作和房租引发冲突。',1),q('Why did viewers mistake the clay fox for a real animal?','its fur and facial details looked realistic','it was made of actual fur','it moved through the gallery','雕塑细节逼真。',2),q('A naturalistic painting is likely to?','show people and settings in a lifelike way','use only abstract symbols with no resemblance','depict only supernatural events','naturalistic 可表示逼真写实。',2,'meaning'),q('Naturalistic can describe?','an unidealised art style or a lifelike appearance','a national citizenship document only','a low-point in a career','该形容词有文艺风格与逼真外观两种用法。',1,'meaning')]);
P('naturally','Naturally is natural plus -ly; it means by nature or without artificial help, and it can also introduce something expected or obvious.',[C('naturally.s1','自然生长','The wild herbs grew naturally along the stream without irrigation, fertiliser, or planting by people.','野草沿着溪流自然生长，没有人工灌溉、施肥或播种。','The wild herbs grew naturally along the stream / without irrigation / fertiliser / or planting by people.','naturally 作副词可表示自然发生、未经人工帮助。','植物没有人工栽培而生长。'),C('naturally.s1','理所当然','Naturally, the pilot checked the weather before departure because the route crossed a mountain range.','飞行员出发前当然要检查天气，因为航线要穿越山脉。','Naturally / the pilot checked the weather before departure / because the route / crossed a mountain range.','句首 naturally 也可表示说话者认为某事显而易见或合乎情理。','检查山地航线天气是预料中的做法。','航空')],M('The herbs grew naturally after workers planted them in pots and supplied artificial light and fertiliser.','The herbs grew naturally beside the stream without being planted or treated.','依靠人工播种和照料不是未经人工帮助的自然生长。','meaning'),[q('How did the wild herbs grow?','without planting or irrigation','in heated pots under artificial light','inside a laboratory flask','它们未经人工栽培而生长。',1),q('Why did the pilot check the weather?','the route crossed mountains','the plane was a sailing ship','the flight had already landed','飞越山脉前检查天气很合理。',1),q('Which sentence uses naturally to mean “without artificial help”?','The flowers grew naturally on the hillside.','Naturally, we should check the forecast.','She naturally assumed he would call.','山坡上的花自行生长体现该义。',1,'meaning'),q('At the start of “Naturally, she checked twice,” naturally means?','as one would expect','in a laboratory-grown way','with no sound at all','句首 naturally 表示“当然、理所当然”。',1,'context')]);
P('nature','Nature came through Old French from Latin natura, “birth or character,” from nasci (“be born”); it can mean the natural world, an inborn character, or the basic type of something.',[C('nature.s1','自然界','The reserve protects nature by restoring wetlands where migratory birds can feed and nest.','保护区通过修复湿地来保护自然界，让候鸟能够觅食和筑巢。','The reserve protects nature / by restoring wetlands / where migratory birds / can feed and nest.','nature 作不可数名词可指自然界的动植物、天气和土地。','湿地为候鸟提供自然栖息地。','生态'),C('nature.s2','天生性格','Despite her quiet nature, Samira speaks confidently when she presents the team’s findings.','尽管萨米拉天性安静，介绍团队发现时仍能自信发言。','Despite her quiet nature / Samira speaks confidently / when she presents / the team’s findings.','nature 也可指人与生俱来的基本性格或倾向。','quiet nature 指她天生较安静的性格。','性格'),C('nature.s3','基本性质','The nature of the complaint changed when investigators found that the missing files had been copied, not deleted.','调查人员发现丢失文件其实被复制而非删除后，这起投诉的性质发生了变化。','The nature of the complaint changed / when investigators found / the missing files had been copied / not deleted.','nature 还可表示事物的基本性质、类型或特征。','新证据改变了投诉事项的性质。','调查')],M('The complaint changed its nature, but the sentence claims that no feature or fact about it changed.','The complaint changed its nature after investigators found the files had been copied rather than deleted.','“性质改变”意味着事件的特点或事实出现变化。','meaning'),[q('What habitat does the reserve restore?','wetlands','a city bus depot','a mountain summit','湿地属于自然界栖息地。',1),q('What is Samira’s nature?','quiet, although she can present confidently','careless about every finding','a kind of bird','nature 在此指天生性格。',2),q('What changed after the file evidence appeared?','the basic character of the complaint','the wetlands’ migration season','Samira’s nationality','nature 可指事件的基本性质。',3,'meaning'),q('Which phrase refers to the natural world?','protect nature','a person’s quiet nature','the nature of a complaint','protect nature 指保护自然界。',1,'context')]);
P('naught','Naught comes from Old English nawiht, literally “no thing”; it means nothing at all or, in older or American usage, zero.',C('naught.s1','归于徒劳','All their careful negotiations came to naught when both sides rejected the final agreement.','双方都拒绝最终协议后，他们此前的认真谈判全都白费了。','All their careful negotiations came to naught / when both sides rejected / the final agreement.','come to naught 是固定表达，表示努力归于徒劳、毫无结果。','谈判未达成协议，努力没有结果。'),M('The negotiations came to naught, and the sentence says they produced a signed agreement accepted by everyone.','The negotiations came to naught because neither side accepted the proposed agreement.','达成且获一致接受的协议不是“毫无结果”。','collocation'),[q('Why did the negotiations come to naught?','both sides rejected the final agreement','both sides signed it happily','the teams forgot to meet','协议被拒，谈判没有结果。'),q('What does come to naught mean?','come to nothing or fail','reach a successful conclusion','become a nationwide event','该固定搭配表示徒劳无果。'),q('In older or American use, naught can mean?','zero','one thousand','a birth certificate','naught 可表示零。',1,'meaning'),q('Which phrase uses naught correctly?','Their plans came to naught.','Their plans came to a naughts.','They naught the plans came.','come to naught 是自然搭配。',1,'collocation')]);
P('naughty','Naughty comes from naught plus -y; it first suggested having nothing or being bad, and now often means playfully disobedient or mildly improper.',[C('naughty.s1','顽皮行为','The naughty puppy stole one sock, then hid under the table when its owner called it back.','这只淘气的小狗偷走一只袜子，主人叫它回来时，它便躲到了桌子底下。','The naughty puppy stole one sock / then hid under the table / when its owner / called it back.','naughty 常形容孩子或动物顽皮、调皮、不听话。','小狗偷袜子后躲藏是淘气行为。'),C('naughty.s2','轻微失礼','The comedian made a mildly naughty joke about the cake’s shape, prompting laughter but not offence.','喜剧演员围绕蛋糕的形状开了个稍微不正经的玩笑，引得大家发笑但没有冒犯谁。','The comedian made a mildly naughty joke / about the cake’s shape / prompting laughter / but not offence.','naughty 也可在轻松语境中形容稍带性暗示或不够正经的言语。','例句明确其程度轻微且没有冒犯。','口语')],M('The naughty puppy obeyed every instruction immediately and never touched anyone’s belongings.','The naughty puppy stole a sock and hid when called.','完全服从且不惹事不符合顽皮义。'),[q('What did the naughty puppy steal?','one sock','the owner’s coat','a paper napkin','小狗偷走一只袜子。',1),q('How was the comedian’s joke described?','mildly improper but not offensive','cruel and insulting','a serious medical warning','naughty joke 在此轻微不正经但不冒犯。',2),q('A naughty child is often?','playfully disobedient','perfectly obedient at all times','unable to speak','naughty 常指顽皮不听话。',1,'meaning'),q('Which remark might be called mildly naughty?','a cheeky double-meaning joke at a friendly party','a formal weather forecast','a direct threat to someone','轻松场合带双关的玩笑可能略带 naughty。',2,'register')]);
P('nausea','Nausea came from Latin nausea and Greek nausia, literally “ship-sickness”; it means an upset feeling in the stomach or strong disgust.',[C('nausea.s1','身体反胃','The rough ferry crossing gave several passengers nausea, so they went outside for fresh air.','渡船颠簸让几名乘客感到恶心，于是他们到外面呼吸新鲜空气。','The rough ferry crossing gave several passengers nausea / so they went outside / for fresh air.','nausea 作名词可指胃里不适、觉得要呕吐的感觉。','船行颠簸导致身体反胃。','健康'),C('nausea.s2','强烈厌恶','The report’s graphic cruelty filled the reader with nausea, and she stopped reading before the final page.','报告中露骨的残酷描写令读者强烈厌恶，她在最后一页前停下了阅读。','The report’s graphic cruelty filled the reader with nausea / and she stopped reading / before the final page.','nausea 也可比喻强烈的厌恶感。','读者因残酷内容而产生厌恶。','情绪')],M('The rough crossing gave the passengers nausea, but the sentence says they felt completely comfortable with no stomach upset.','The rough crossing gave the passengers nausea, leaving them feeling sick.','完全舒适、毫无胃部不适与 nausea 相矛盾。'),[q('What caused the passengers’ nausea?','the rough ferry crossing','the quiet reading room','the plant’s natural growth','渡船颠簸让乘客反胃。',1),q('What did the reader feel toward the report?','strong disgust','a pleasant appetite','a national loyalty','残酷内容引发强烈厌恶。',2),q('Nausea can mean?','an upset stomach or strong disgust','a short nap','a vessel’s route','nausea 有身体不适和厌恶感两义。',1,'meaning'),q('Which condition is nausea?','a queasy feeling as if one might vomit','a feeling of pride in a nation','a calm, hungry stomach','反胃、想吐的感觉是 nausea。',1,'context')]);
P('nauseous','Nauseous is nausea plus -ous; in this entry it means feeling as if one might vomit.',C('nauseous.s1','恶心感觉','After the spinning ride stopped, Priya felt nauseous and sat quietly until her stomach settled.','旋转游乐设施停下后，普里娅感到恶心，静坐到胃里舒服些为止。','After the spinning ride stopped / Priya felt nauseous / and sat quietly / until her stomach settled.','nauseous 作形容词描述人的反胃感。','主语 felt nauseous 并等待胃部不适缓解。'),M('After the ride, Priya felt nauseous, but the sentence says she felt hungry, comfortable, and entirely well.','After the ride, Priya felt nauseous and needed time for her stomach to settle.','完全舒服、没有反胃感与 nauseous 不符。'),[q('What made Priya feel nauseous?','the spinning ride','a quiet walk through a garden','a new jacket','旋转设施停下后她感到恶心。'),q('What did Priya do?','sat quietly until her stomach settled','immediately started another spinning ride','called the navy','她等胃部不适缓解。'),q('Nauseous means?','feeling as if you might vomit','feeling very hungry','being unable to see far away','nauseous 指觉得可能要呕吐。'),q('Which sentence uses nauseous for the person’s feeling?','I felt nauseous after the rough boat trip.','The report nauseated its readers.','The nauseous smell filled the room.','例句中 nauseous 描述人的反胃感。',1,'grammar')]);
P('nautical','Nautical comes from Greek nautikos, “of ships,” from naus (“ship”); it relates to ships, sailors, or sailing.',C('nautical.s1','航海用品','The captain checked the nautical chart before entering the bay because shallow rocks were marked near the eastern shore.','驶入海湾前，船长查看了航海图，因为东岸附近标出了浅水礁石。','The captain checked the nautical chart / before entering the bay / because shallow rocks / were marked near the eastern shore.','nautical 作形容词修饰与船舶、海员或航行有关的事物。','海图提供航行水域和暗礁信息。','航海'),M('The captain used a nautical chart to find the nearest bus stop in the inland shopping centre.','The captain used a nautical chart to locate shallow rocks in the bay.','航海图用于海上导航，而不是寻找商场公交站。','confusable'),[q('Why did the captain check the chart?','to locate shallow rocks near the shore','to learn a national anthem','to measure a nanometer','海图标明海湾附近的浅水礁石。'),q('A nautical chart is connected with?','ships and sailing','forest gardening','stage narration','nautical 指航海相关。'),q('Which object is nautical?','a ship’s compass','a theatre ticket','a kitchen napkin','船用罗盘属于航海用品。',1,'context'),q('The Greek source naus means?','ship','birth','nothing','naus 是“船”。',1,'word-formation')]);
P('naval','Naval comes from Old French naval and Latin navalis, “of ships,” from navis (“ship”); it relates to a country’s navy or its warships.',[C('naval.s1','海军事务','The naval academy trains officers for service in the country’s fleet and teaches them maritime law.','海军学院培养该国舰队军官，并教授海事法。','The naval academy trains officers / for service in the country’s fleet / and teaches them / maritime law.','naval 作形容词表示与海军有关。','学院为海军舰队培养军官。','军事'),C('naval.s2','军舰舰队','The harbour authority moved the naval vessels away from the commercial pier before the storm arrived.','风暴来临前，港务部门把军舰从商业码头移走。','The harbour authority moved the naval vessels / away from the commercial pier / before the storm arrived.','naval 也可修饰军舰或舰队，强调军用船只。','这些船是军事舰艇。','军事')],M('The harbour called a privately owned sightseeing yacht a naval vessel even though it had no military role.','The harbour called the armed fleet’s warship a naval vessel.','没有军方用途的观光游艇不是军舰。','confusable'),[q('What does the naval academy train?','officers for the country’s fleet','commercial tour guides','wildlife naturalists','海军学院培养舰队军官。',1),q('Where were the naval vessels moved from?','the commercial pier','the mountain road','the museum gallery','军舰被移离商业码头。',2),q('Naval most directly relates to?','a country’s navy','all civilian boats','every kind of water plant','naval 指海军事务。',1,'meaning'),q('Which is a naval vessel?','a warship in a country’s fleet','a private sightseeing yacht','a river ferry carrying commuters','军用舰艇属于 naval vessel。',2,'context')]);
P('navigable','Navigable comes from Latin navigabilis, from navigare (“sail”); it describes water deep or wide enough for travel or a system easy to move through.',[C('navigable.s1','可通航水域','After the dredging work, the channel became navigable for small cargo boats even at low tide.','疏浚后，即使在低潮时，这条水道也可供小型货船通行。','After the dredging work / the channel became navigable / for small cargo boats / even at low tide.','navigable 作形容词可描述宽度和水深足够船只通过的水域。','疏浚后水道能让小型货船通行。','航海'),C('navigable.s2','易于浏览','The archive website is navigable on a phone because its menus are clear and every collection has a direct link.','档案网站在手机上也容易浏览，因为菜单清楚，每个馆藏都有直达链接。','The archive website is navigable on a phone / because its menus are clear / and every collection / has a direct link.','navigable 也可表示网站或复杂系统容易找到路径、操作浏览。','清晰菜单和链接让用户容易找到内容。','技术')],M('The channel was navigable for cargo boats even though it was too shallow for any vessel to pass.','The channel was navigable for small cargo boats after dredging made it deep enough.','无法让船只通过的浅水道不可通航。'),[q('What could use the channel after dredging?','small cargo boats','large aircraft','commuters on a bus','水道供小型货船通行。',1),q('Why is the archive website navigable?','its menus are clear and collections link directly','all its pages are hidden','it has no categories','菜单清晰、链接直达让网站易浏览。',2),q('A navigable river is?','deep or wide enough for boats to travel on','too shallow for any boat','a river with no water','navigable 水域可供船只通行。',1,'meaning'),q('A navigable website is?','easy for users to move through and find pages','one with no links or menus','one that only works as a paper chart','navigable 也可指容易浏览。',2,'context')]);
P('navigate','Navigate came from Latin navigare, “sail or steer a ship,” from navis (“ship”) and agere (“drive”); it means find a route, direct a vehicle, or manage a complex system.',[C('navigate.s1','确定路线','The hikers used a map and compass to navigate through the forest when the marked trail disappeared under snow.','标记步道被雪覆盖后，徒步者用地图和指南针在森林中辨明路线。','The hikers used a map and compass / to navigate through the forest / when the marked trail / disappeared under snow.','navigate 作动词可表示借助地图或仪器找到方向和路线。','地图和指南针帮助他们找到路。'),C('navigate.s2','驾驶航行','The pilot navigated the aircraft around the storm using updated radar information from air traffic control.','飞行员利用空中交通管制提供的最新雷达信息，驾驶飞机绕过风暴。','The pilot navigated the aircraft around the storm / using updated radar information / from air traffic control.','navigate 也可指沿选定航线驾驶船、飞机或汽车。','飞行员操纵飞机绕开风暴。','航空'),C('navigate.s3','处理复杂系统','New staff learn to navigate the benefits website so they can find forms and submit claims without assistance.','新员工学习如何浏览福利网站，以便无需协助也能找到表格并提交申请。','New staff learn to navigate the benefits website / so they can find forms / and submit claims / without assistance.','navigate 还可比喻在复杂地点、网站或规则中找到路径并顺利处理。','员工在网站中寻找所需表格。','技术')],M('The pilot navigated around the storm by flying directly into its centre without changing course.','The pilot navigated around the storm by using radar to choose a safer route.','直接飞入风暴中心不是绕开风暴。'),[q('What helped hikers navigate through the snowy forest?','a map and compass','a paper napkin','a film narrator','地图和指南针辅助辨认路线。',1),q('What did the pilot navigate around?','a storm','a monastery wall','a national election','飞行员绕开风暴。',2),q('What does navigate a website mean?','find one’s way through its pages','sail a ship across an ocean','make a new website mysterious','navigate 可指在网站中找到所需内容。',3,'meaning'),q('Which use refers to directing a vehicle?','The pilot navigated the aircraft around the storm.','The hikers navigated by a map.','The staff navigated the benefits site.','驾驶飞机沿航线行驶属于该义。',2,'context')]);
P('navigation','Navigation comes from Latin navigatio, “sailing or a voyage,” from navigare (“sail”); it means finding a route or travelling by ship or aircraft.',[C('navigation.s1','路线指引','The navigation system rerouted the driver when roadworks closed the bridge ahead.','前方桥梁因施工封闭后，导航系统为司机重新规划了路线。','The navigation system rerouted the driver / when roadworks closed / the bridge ahead.','navigation 作名词可指确定旅行方向和路线的过程或系统。','系统根据封路情况重新规划路线。','技术'),C('navigation.s2','海空航行','Early polar navigation by ship required careful timing because ice could close the passage within hours.','早期的极地船舶航行需要精确把握时机，因为冰层可能在数小时内封闭航道。','Early polar navigation by ship / required careful timing / because ice could close the passage / within hours.','navigation 也可指乘船或飞机旅行、航行。','例句指船只在极地海域行驶。','航海')],M('The navigation system rerouted the driver, but the sentence says it provided no route or direction at all.','The navigation system gave the driver a new route around the closed bridge.','重新规划路线正是提供导航方向。'),[q('Why did the navigation system reroute the driver?','the bridge was closed for roadworks','the weather became warmer','the driver changed nationality','施工封桥导致路线变化。',1),q('What made polar navigation difficult?','ice could close the passage quickly','the ship had a paper napkin','there were too many road signs','冰层可迅速封住航道。',2),q('Navigation can mean?','route-finding or travel by ship or aircraft','a national identity','an art movement','navigation 可指导航或船舶、航空航行。',1,'meaning'),q('Which is a navigation aid?','a system that finds a route around a closed road','a naturalist’s field notebook','a nautical joke','重新规划封路路线的系统是导航工具。',1,'context')]);
P('navigational','Navigational is navigation plus -al and means used for, or connected with, finding and following a route.',C('navigational.s1','路线辅助','The crew checked the navigational lights before departure to make the vessel visible to other ships after dark.','出发前，船员检查了航行灯，确保天黑后其他船只能够看到本船。','The crew checked the navigational lights / before departure / to make the vessel visible / to other ships after dark.','navigational 作形容词修饰用于确定航线或保障航行的设备。','航行灯帮助船只在夜间辨认位置。','航海'),M('The crew called the lights navigational even though they were decorative and could not help identify or guide a vessel.','The crew called the lights navigational because they helped other ships locate the vessel at night.','纯装饰且不能帮助航行的灯不是 navigational equipment。'),[q('When did the crew check the lights?','before departure','after the ship had sunk','during a national election','船员出发前检查航行灯。'),q('Why were the lights important after dark?','they made the vessel visible to other ships','they measured the channel depth','they replaced the compass','航行灯有助于夜间识别船只。'),q('Navigational most nearly means?','related to route-finding or guiding a vessel','related to natural history','related to a person’s birthplace','navigational 与导航、航行相关。',1,'meaning'),q('Which item is navigational equipment?','a ship’s compass','a restaurant napkin','a painter’s naturalistic brush','罗盘用于导航。',1,'context')]);
P('navigator','Navigator comes from Latin navigator, “sailor,” from navigare (“sail”); it names a person who plans a route or a device that guides a vehicle.',C('navigator.s1','领航员','The navigator plotted a course around the reef before the fishing boat left the harbour.','渔船离港前，领航员绘制了一条绕过暗礁的航线。','The navigator plotted a course / around the reef / before the fishing boat / left the harbour.','navigator 作名词可指为船舶或飞机规划路线的人，也可指导航设备。','领航员提前设计安全航线。','航海'),M('The navigator plotted a course through the reef by ignoring the chart and choosing the most dangerous route.','The navigator plotted a safe course around the reef before departure.','故意忽视海图并选择危险路线不符合安全领航语境。','meaning'),[q('What did the navigator plot?','a course around the reef','a national boundary','a naturalist’s field route','领航员规划了绕礁路线。'),q('When was the course planned?','before the boat left harbour','after it had passed the reef','before the reef formed','离港前就绘制航线。'),q('A navigator can be?','a person planning a route or a guiding device','a person who narrates a film only','a kind of navy blue','navigator 可指领航员或导航设备。',1,'meaning'),q('Which person is a navigator?','a crew member who plots a ship’s course','a passenger reading a novel','a naturalist cataloguing plants','绘制船舶航线的人是 navigator。',1,'context')]);
P('navy','Navy came through Old French navie (“fleet”) from Latin navis (“ship”); it means a country’s sea-fighting service, a very dark blue, or the colour navy blue.',[C('navy.s1','海军部队','The navy sent a rescue ship to the island after a storm damaged the harbour and cut off the ferry.','风暴损坏港口、渡船停航后，海军派出救援船前往该岛。','The navy sent a rescue ship / to the island / after a storm damaged the harbour / and cut off the ferry.','navy 作名词可指国家武装力量中负责海上作战的部分。','海军派船执行救援任务。','军事'),C('navy.s2','深蓝颜色','The uniform’s navy matched the dark blue stripe on the team’s flag.','制服的海军蓝与队旗上的深蓝条纹相配。','The uniform’s navy matched / the dark blue stripe / on the team’s flag.','navy 作名词可指一种很深的蓝色。','此处 navy 指颜色。','色彩'),C('navy.s3','深蓝色的','She wore a navy coat to the ceremony, choosing the dark blue one rather than the black version.','她穿了一件海军蓝外套参加仪式，选的是深蓝款而非黑色款。','She wore a navy coat to the ceremony / choosing the dark blue one / rather than the black version.','navy 也可作形容词修饰深蓝色的衣物或物件。','navy 修饰 coat 表示颜色。','服饰')],M('The navy dispatched a rescue ship, but the sentence says no ship or sea-service personnel were involved.','The navy dispatched one of its ships to assist the island.','派出舰艇参与救援说明海军确实介入。','meaning'),[q('What did the navy send to the island?','a rescue ship','a naturalist’s notebook','a film narrator','海军派出救援船。',1),q('What colour matched the flag’s stripe?','a very dark blue','bright yellow','pale green','navy 可指很深的蓝色。',2),q('In “a navy coat,” navy is a/an?','adjective describing a dark blue colour','noun for a route planner','verb meaning steer a ship','navy 在此修饰 coat，表示深蓝色。',3,'grammar'),q('Which use means a country’s sea-fighting force?','The navy rescued the islanders.','She wore a navy coat.','The uniform was navy.','此句中 navy 指海军部队。',1,'meaning')]);
})();

})();
